NAME = 'CebPinadayag: Cebuano Pinadayag'
BOOK = 'Proverbs'

CHAPTERS = {
    1: {
        1: 'Ang mga proverbio ni Salomon anak nga lalake ni David, hari sa Israel:',
        2: 'Sa paghibalo sa kaalam ug pahamangno; Sa pag-ila sa mga pulong salabutan;',
        3: 'Sa pagdawat sa pahamangno sa maalamon nga pagbuhat, Sa pagkamatarung ug sa justicia ug sa pagkatul-id;',
        4: 'Sa paghatag ug salabutan sa mga walay-pagtagad, Alang sa batan-ong lalake ang kahibalo ug kabuot:',
        5: 'Aron ang tawo nga manggialamon makadungog, ug magadugang sa kinaadman; Ug aron ang tawo nga masinabuton makabaton sa maayong mga tambag:',
        6: 'Sa pagsabut sa usa ka proverbio, ug sa usa ka pulong salabton, Mga pulong sa manggialamon, ug sa ilang mga tigmo.',
        7: 'Ang pagkahadlok kang Jehova maoy sinugdan sa kahibalo; Apan ang mga buangbuang nagatamay sa kaalam ug pahamangno.',
        8: 'Anak ko, pamatia ang pahamangno sa imong amahan, Ug ayaw pagbiyai ang pagtulon-an sa imong inahan:',
        9: 'Kay sila maingon sa usa ka purongpurong bulak sa gracia sa imong ulo, Ug mga kulentas sa imong liog.',
        10: 'Anak ko, kong ang mga makasasala mag-ulog-ulog kanimo, Ayaw pag-uyon kanila.',
        11: 'Kong sila moingon: Umuban ka kanamo, Managbanhig kita alang sa dugo; Managbanhig kita sa tago alang sa inocente sa walay pasikaran;',
        12: 'Lamyon nato sila nga buhi ingon sa Sheol, Ug ang tibook, ingon niadtong nangahulog sa gahong;',
        13: 'Makaplagan ta ang tanang bililhon nga manggad; Pagapun-on ta ang atong mga balay sa inagaw;',
        14: 'Mag-ambitay kita sa imong kapalaran sa among taliwala; Usahon ta ang atong puntil:',
        15: 'Anak ko, ayaw paglakat sa dalan uban kanila; Ilikay ang imong tiil gikan sa ilang alagianan:',
        16: 'Kay ang ilang mga tiil nanagdalagan ngadto sa kadautan, Ug sila nanagdali aron sa pag-ula ug dugo.',
        17: 'Kay sa kawang lamang ang pukot nga giladlad Diha sa atubangan sa bisan unsang langgam:',
        18: 'Ug sila nanaghubong tungod sa ilang kaugalingong dugo; Sila nagabanhig sa tago alang sa ilang kaugalingong mga kinabuhi.',
        19: 'Busa mao man ang mga dalan sa tagsatagsa nga hakog sa ganancia; Kini nagakuha sa kinabuhi sa mga tag-iya niana.',
        20: 'Ang kaalam nagasinggit sa makusog sa kadalanan; Siya nagasulti sa iyang tingog diha sa halapad nga mga dapit;',
        21: 'Siya nagasinggit sa mga masabang dapit sa kadalanan; Sa dapit sa mga ganghaan, Diha sa ciudad, siya nagasulti sa iyang mga pulong:',
        22: 'Unsang kadugayon, kamo nga mga walay-pagtagad, nga higugmaon ninyo ang pagkawalay-pagtagad? Ug ang mga mayubiton mahimuot kanila sa pagyubit, Ug ang mga buang sa pagdumot sa kinaadman?',
        23: 'Bumalik kamo sa akong pagbadlong: Ania karon, ibubo ko ang akong espiritu sa ibabaw ninyo; Akong ipahibalo ang akong mga pulong kaninyo.',
        24: 'Tungod kay ako nagtawag, ug kamo mingbalibad; Akong gibayaw ang akong kamot, ug walay tawo nga nagtagad;',
        25: 'Apan gisalikway ninyo ang tanan ko nga tambag, Ug dili mobuot sa akong pagbad-long:',
        26: 'Ako usab mokatawa sa adlaw sa inyong pagkaalaut; Ako magatamay sa diha nga moabut ang inyong kahadlok;',
        27: 'Sa diha nga moabut ang inyong kahadlok sama sa usa ka bagyo, Ug moabut ang inyong pagkaalaut sama sa usa ka alimpulos; Sa diha nga ang kasakit ug kaguol modangat kaninyo.',
        28: 'Unya sila magasangpit kanako, apan ako dili motubag; Sila magapangita nga masingkamoton kanako, apan sila dili makakaplag kanako.',
        29: 'Tungod kay ilang gidumtan ang kinaadman, Ug wala magpili sa pagkahadlok kang Jehova,',
        30: 'Sila wala mobuot sa akong tambag, Sila nagtamay sa tanan ko nga pagbadlong.',
        31: 'Busa sila magakaon sa bunga sa ilang kaugalingong dalan, Ug mangabusog sa ilang kaugalingong mga lalang.',
        32: 'Kay ang pagkasukihan sa mga tawong walay-pagtagad mopatay kanila, Ug ang mapasagarong pagpatuyang sa mga buang molaglag kanila.',
        33: 'Apan bisan kinsa nga mamati kanako magapuyo sa kasigurohan, Ug magamalinawon nga walay kahadlok sa kadautan.',
    },
    2: {
        1: 'Anak ko, kong dawaton mo ang akong mga pulong, Ug tigumon mo ang akong mga sugo diha kanimo;',
        2: 'Aron nga ikiling mo ang imong igdulungog ngadto sa kaalam, Ug bansayon mo ang imong kasingkasing sa pagsabut;',
        3: 'Oo, kong ikaw magasangpit sa salabutan, Ug magapatugbaw sa imong tingog alang sa pagpakasabut;',
        4: 'Kong ikaw mangita kaniya ingon nga salapi, Ug magapangita kaniya ingon sa tinipigan nga mga bahandi:',
        5: 'Unya ikaw makasabut sa pagkahadlok kang Jehova, Ug hikaplagan mo ang kahibalo sa Dios.',
        6: 'Kay si Jehova mohatag ug kaalam; Gikan sa iyang baba magagula ang kahibalo ug pagpakasabut:',
        7: 'Siya magatigum ug halalum nga kaalam alang sa matul-id; Siya mao ang taming kanila nga nagalakat sa pagkahingpit sa kasingkasing;',
        8: 'Aron iyang mabantayan ang mga alagianan sa justicia, Ug ampingan ang dalan sa iyang mga balaan.',
        9: 'Unya masabut mo ang pagkamatarung ug ang justicia, Ug sa pagkatul-id, oo, ang tagsatagsa ka maayong alagianan.',
        10: 'Kay ang kaalam mosulod ngadto sa imong kasingkasing, Ug ang kahibalo makapahimuot sa imong kalag;',
        11: 'Ang pagkabuotan magabantay sa ibabaw nimo; Ang pagpakasabut magahupot kanimo:',
        12: 'Aron sa pagluwas kanimo gikan sa dalan sa dautan, Gikan sa mga tawong nagsulti sa mga binalit-ad nga butang;',
        13: 'Nga nagabiya sa mga alagianan nga matul-id, Aron sa paglakat sa mga dalan sa kangitngit;',
        14: 'Nga nagamaya sa pagbuhat ug dautan, Ug nagakalipay sa pagkabinalitad sa tawong dautan;',
        15: 'Nga mga baliko sa ilang mga dalan, Ug mga sukwahi sa ilang mga alagianan:',
        16: 'Aron sa pagluwas kanimo gikan sa babaye nga dumuloong, Bisan gikan sa dumuloong nga nagaulog-ulog pinaagi sa iyang mga pulong;',
        17: 'Nga nagabiya sa higala sa iyang pagkabatan-on, Ug nahikalimot sa tugon sa iyang Dios:',
        18: 'Kay ang iyang balay nagaharag ngadto sa kamatayon, Ug ang iyang mga alagianan ngadto sa mga minatay;',
        19: 'Walay mahiadto kaniya nga mahibalik pag-usab, Ni makadangat sila ngadto sa mga alagianan sa kinabuhi:',
        20: 'Aron ikaw magalakaw sa dalan sa mga maayong tawo, Ug magabantay sa mga alagianan sa mga matarung.',
        21: 'Kay ang mga matul-id magapuyo sa yuta, Ug ang hingpit magapabilin diha niana.',
        22: 'Apan ang mga dautan pagaputlon gikan sa yuta, Ug ang mabudhion pagalukahon gikan niini.',
    },
    3: {
        1: 'Anak ko, ayaw hikalimti ang akong Kasugoan; Apan pabantayi sa imong kasingkasing ang akong mga sugo:',
        2: 'Kay ang kadugayon sa mga adlaw, ug mga tuig sa kinabuhi, Ug pakigdait, sila igadugang kanimo.',
        3: 'Ayaw pagpabiyaa kanimo ang kalolot ug kamatuoran: Ihigot mo sila sa imong liog; Isulat mo sila ibabaw sa papan sa imong kasingkasing:',
        4: 'Aron ikaw makakaplag sa kalomo ug maayong salabutan Sa atubangan sa Dios aug sa tawo.',
        5: 'Sumalig ka kang Jehova sa bug-os mong kasingkasing, Ug ayaw pagsalig sa imong kaugagalingong salabutan:',
        6: 'Sa tanan nimong mga dalan ilha siya, Ug siya magamando sa imong mga alagianan.',
        7: 'Ayaw pagpakamaalamon sa imong kaugalingong mga mata; Kahadlokan mo si Jehova, ug pahalayo gikan sa dautan:',
        8: 'Kana mahimong kaayohan sa imong pusod, Ug utok sa imong mga bukog.',
        9: 'Pasidunggi si Jehova pinaagi sa imong manggad, Ug sa mga inunahang bunga sa tanan mong abut:',
        10: 'Aron ang imong mga kamalig mapuno sa kadaghan, Ug ang imong pug-anan magaawas sa bag-ong vino.',
        11: 'Anak ko, ayaw pagtamaya ang pagcastigo ni Jehova; Ni magsubo ka sa iyang pagbadlong:',
        12: 'Kay kinsa kadto nga gihigugma ni Jehova iyang ginabadlong, Maingon sa usa ka amahan sa anak nga iyang gikahimut-an.',
        13: 'Malipayon ang tawo nga makakaplag sa kaalam, Ug ang tawo nga makakab-ut sa pagsabut.',
        14: 'Kay ang pagpakabaton niini labi pang maayo kay sa pagmanggad sa salapi, Ug ang kaayohan niini labaw pa kay sa fino nga bulawan.',
        15: 'Siya labi pang bililhon kay sa mga rubi: Ug walay mausa sa mga butang nga imong ginatinguha nga ikatanding niana.',
        16: 'Ang hataas nga mga adlaw anaa sa iyang kamot nga too; Diha sa iyang kamot nga wala anaa ang bahandi ug kadungganan.',
        17: 'Ang iyang mga dalan maoy mga dalan sa kahimut-anan, Ug ang tanan niyang mga alagianan mga pakigdait.',
        18: 'Siya maoy usa ka kahoy sa kinabuhi kanila nga mokupot kaniya: Ug malipayon ang tagsatagsa nga magahawid kaniya.',
        19: 'Si Jehova pinaagi sa kaalam mitukod sa yuta; Pinaagi sa pagsabut iyang gitukod ang kalangitan.',
        20: 'Pinaagi sa iyang kinaadman ang mga kahiladman nangaabli, Ug ang kalangitan nagapatagas sa tun-og.',
        21: 'Anak ko, ayaw sila pagpabulaga gikan sa imong mga mata; Batoni ang halalum nga kaalam ug ang pagkabuotan:',
        22: 'Sa ingon niana sila mahimong kinabuhi alang sa imong kalag, Ug gracia sa imong liog.',
        23: 'Unya magalakat ikaw sa imong dalan nga may kasigurohan, Ug ang imong tiil dili mahapangdol.',
        24: 'Sa diha nga ikaw mohigda, dili ka malisang: Oo, ikaw mohigda, ug ang imong pagkatulog matam-is.',
        25: 'Ayaw kalisang sa hinanali nga kahadlok, Ni sa pagkalaglag sa dautan, kong kini modangat:',
        26: 'Kay si Jehova mao ang imong kasaligan, Ug magabantay sa imong tiil nga dili hidakpan.',
        27: 'Ayaw pag ihikaw ang kaayohan gikan kanila diin kini gikinahanglan, Sa diha nga kini anaa sa gahum sa imong kamot ang pagbuhat niini.',
        28: 'Ayaw pag-ingon sa imong isigkatawo: Lakat, ug bumalik ka pagusab, Ug sa pagkaugma ako mohatag; Sa diha nga ikaw aduna na niana.',
        29: 'Ayaw pagtinguha sa kadautan batok sa imong isigkatawo, Sa makita mo nga siya nagapuyo sa kasigurohan tupad kanimo.',
        30: 'Ayaw pagpakig-away sa usa ka tawo sa walay gipasikaran, Kong siya wala maghilabut kanimo.',
        31: 'Ayaw kasinahi ang tawo nga malupigon, Ug ayaw pagpilia ang iyang mga dalan.',
        32: 'Kay ang tawo nga sukwahi maoy usa ka dulumtanan kang Jehova; Apan ang iyang pagpakighigala anaa uban sa mga tawong matul-id.',
        33: 'Ang pagpanghimaraut ni Jehova anaa sa balay sa dautan; Apan iyang pagapanalanginan ang puloy-anan sa tawong matarung.',
        34: 'Sa pagkatinuod siya nagayubit sa mga mayubiton; Apan siya nagahatag ug gracia sa mga mapainubsanon.',
        35: 'Ang manggialamon makapanunod sa himaya; Apan ang kaulaw maoy makapauswag sa mga buang.',
    },
    4: {
        1: 'Pamatia, mga anak ko, ang pahamatngon sa usa ka amahan, Ug matngoni ang pagkahibalo sa pagsabut:',
        2: 'Kay ako nagahatag kaninyo ug maayong pagtulon-an; Ayaw ninyo pagbiyai ang akong balaod.',
        3: 'Kay ako usa ka anak nga lalake sa akong amahan, Batan-on ug mao ray pinalangga sa panan-aw sa akong inahan.',
        4: 'Ug iyang gitudloan ako, ug mi-ingon kanako: Patipigi sa imong kasingkasing ang akong mga pulong; Bantayi ang akong mga sugo, ug mabuhi ka;',
        5: 'Batoni ang kaalam, batoni ang pagsabut; Ayaw hikalimti, ni pag-ayran mo ang mga pulong nga gikan sa akong baba;',
        6: 'Ayaw siya pagbiyai, ug siya magapanalipod kanimo; Higugmaa siya, ug siya magabantay kanimo.',
        7: 'Ang kaalam maoy labaw nga butang; busa batoni ang kaalam; Oo, uban sa tanan mo nga pagatinguhaon batoni ang pagsabut.',
        8: 'Ipahitaas siya, ug siya magapauswag kanimo; Siya magadala kanimo ngadto sa kadungganan, kong ikaw mogakus kaniya.',
        9: 'Siya magahatag kanimo sa usa ka purongpurong nga bulak sa gracia; Usa ka purongpurong sa katahum iyang igahatag kanimo.',
        10: 'Pamati, Oh anak ko, ug dawata ang akong mga ipamulong; Ug ang mga katuigan sa imong kinabuhi magadaghan.',
        11: 'Ako nagtudlo kanimo sa dalan sa kaalam; Ako nagmando kanimo sa mga alagianan sa katul-iran.',
        12: 'Kong ikaw magalakaw, ang imong mga lakang dili pagamub-on; Ug kong ikaw magadalagan, dili ka mahisokamod.',
        13: 'Hawiri gayud ang pagpahamangno; ayaw siya pagbuhii: Bantayi siya; kay siya mao ang imong kinabuhi.',
        14: 'Ayaw pagsulod sa alagianan sa dautan, Ug ayaw paglakat sa dalan sa mga tawong dautan.',
        15: 'Likayi kini, ayaw pag-agi haduol niini; Tumipas ka gikan niini, ug padayon.',
        16: 'Kay sila dili matulog, gawas kong sila makabuhat ug dautan; Ug ang ilang pagkatulog mawala, gawas kong sila makapahulog sa uban.',
        17: 'Kay sila magakaon sa tinapay sa kadautan, Ug magainum sa vino sa pagpanlupig.',
        18: 'Apan ang alagianan sa matarung ingon sa banagbanag sa kahayag, Nga nagakasanag sa kahayag ngadto sa pagkahingpit sa adlaw.',
        19: 'Ang dalan sa tawong dautan ingon sa kangitngit: Sila dili manghibalo kong usa ang ilang napangdolan.',
        20: 'Anak ko, pagmatngon sa akong mga pulong; Ikiling ang imong igdulungog sa akong mga gipamulong.',
        21: 'Ayaw sila pagpabulaga gikan sa imong mga mata; Tipigi sila sa kinataliwad-an sa imong kasingkasing.',
        22: 'Kay sila kinabuhi alang niadtong nanagpangita kanila, Ug kaayohan sa ilang tibook nga unod.',
        23: 'Ampingi ang imong kasingkasing sa tanang pagsingkamot; Kay gikan niini magagula ang dagkung butang sa kinabuhi.',
        24: 'Isalikway gikan kanimo ang usa ka masinalaagon nga baba, Ug ipahilayo gikan kanimo ang mga ngabil nga masukihon.',
        25: 'Itutok ang pagtan-aw sa imong mga mata sa unahan, Ug itutok ang imong mga tabon-tabon sa atubangan nimo.',
        26: 'Pataga ang alagianan sa imong mga tiil, Ug tukora sa matul-id gayud ang tanan mong mga dalan.',
        27: 'Ayaw pagliso sa too mong kamot ni sa wala: Kuhaa ang imong tiil gikan sa dautan.',
    },
    5: {
        1: 'Anak ko, pagmatngon sa akong kaalam; Ikiling ang imong igdulungog sa akong salabutan:',
        2: 'Aron ikaw magabantay sa pagkabuotan, Ug aron ang imong mga ngabil magatipig ug kinaadman.',
        3: 'Kay ang mga ngabil sa usa ka dumuloong babaye nagpatolo ug dugos, Ug ang iyang baba labi pang mahinlo kay sa lana:',
        4: 'Apan sa katapusan siya mapait ingon sa panyawan, Mahait ingon sa usa ka espada nga duhay sulab.',
        5: 'Ang iyang mga tiil nagakanaug ngadto sa kamatayon; Ang iyang mga lakang gitunob ibabaw sa Sheol;',
        6: 'Busa siya dili makakaplag sa patag nga alagianan sa kinabuhi: Ang iyang mga dalan mabalhinon, ug siya wala mahibalo niini.',
        7: 'Busa karon, mga anak ko, patalinghug kamo kanako, Ug ayaw pagbiya gikan sa mga pulong sa akong baba.',
        8: 'Ipahilayo ang imong dalan gikan kaniya, Ug ayaw pagpahaduol sa pultahan sa iyang balay;',
        9: 'Tingali unya ikaw magahatag sa imong kadungganan ngadto sa lain, Ug ang imong mga tuig ngadto sa madaugdaugon;',
        10: 'Tingali unya ang mga dumuloong mapuno sa imong kusog, Ug ang imong mga pagpangabudlay anha sa balay sa usa ka lumalangyaw,',
        11: 'Ug ikaw mag-agulo sa imong kaulahian, Sa diha nga mangaut-ut ang imong unod ug ang imong lawas,',
        12: 'Ug magaingon: Giunsa ko ang pagdumot sa pahamangno, Ug ang akong kasingkasing nagtamay sa pagbadlong;',
        13: 'Ni gituman ko ang tingog sa akong mga magtutudlo, Ni nagkiling ako sa akong igdulungog kanila nga nagpahamangno kanako!',
        14: 'Ako haduol kaayo sa tanang kadautan Sa kinataliwad-an sa pagkatigum ug sa katilingban.',
        15: 'Imna ang mga tubig gikan sa kaugalingon mong sudlanan, Ug ang mga tubig nga nagaagay gikan sa kaugalingon mong atabay.',
        16: 'Patibulaagon mo ba ang imong mga tubod sa halayong dapit, Ug ang mga taburan sa tubig diha sa kadalanan?',
        17: 'Himoa sila nga imo lamang, Ug dili alang sa mga dumuloong uban kanimo.',
        18: 'Papanalangini ang imong tuburan; Ug pagmalipayon diha sa asawa sa imong pagkabatan-on.',
        19: 'Ingon sa usa ka mahigugmaong lagsaw nga dumalaga ug sa usa ka makapahimuot nga gasela, Tugoti nga ang iyang mga dughan magatagbaw kanimo sa tanang mga panahon; Ug magpalugos ka sa kanunay sa iyang gugma.',
        20: 'Kay ngano man ikaw, anak ko, nga magpalugos sa usa ka dumuloong babaye, Ug magahalog sa sabakan sa usa ka lumalangyaw?',
        21: 'Kay ang mga dalan sa tawo anaa sa atubangan sa mga mata ni Jehova; Ug gipatag niya ang tanang mga alagianan niya.',
        22: 'Ang iyang kaugalingong kasal-anan modakop sa dautan, Ug siya magapus sa mga higot sa iyang sala.',
        23: 'Siya mamatay tungod sa pagkakulang sa pahamangno; Ug sa pagkadaku sa iyang pagkabuang siya mahisalaag.',
    },
    6: {
        1: 'Anak ko, kong ikaw mahimong magpapasalig alang sa imong isigkatawo, Kong ikaw sa imong mga kamot makadagmal sa usa ka dumuloong;',
        2: 'Ikaw nabitik tungod sa mga pulong sa imong baba, Ikaw nadakpan tungod sa mga pulong sa imong baba.',
        3: 'Buhata kini karon, anak ko, ug gumawas ka sa imong kaugalingon, Sanglit ikaw nagapus sa kamot sa imong isigkatawo: Lakaw, magpaubos ka sa imong kaugalingon, ug magpakilooy sa imong isigkatawo;',
        4: 'Ayaw paghatagi ug katulog ang imong mga mata, Ni paghinanok ang imong mga tabon-tabon;',
        5: 'Gumawas ka sa imong kaugalingon ingon sa usa ka lagsaw gikan sa kamot sa mangangayam, Ug ingon sa usa ka langgam gikan sa kamot sa mangangayam sa langgam.',
        6: 'Umadto ka sa olmigas, ikaw nga tapulan; Palandunga ang iyang mga dalan, ug pagmaalamon:',
        7: 'Nga bisan walay pangulo, Capatas, kun punoan,',
        8: 'Nagaandam sa iyang kalan-on sa ting-init, Ug nagahipos sa iyang makaon sa ting-ani.',
        9: 'Unsa ang kadugayon nga ikaw matulog, Oh tapulan? Anus-a ka mobangon gikan sa imong pagkatulog?',
        10: 'Usa ka diyutay nga pagkatulog, usa ka diyutay nga paghinanok, Usa ka diyutay nga pagkiyugpos sa mga kamot aron sa pagkatulog:',
        11: 'Busa ang imong pagkakabus modangat ingon sa usa ka tulisan, Ug ang imong kawalad-on ingon sa usa ka tawo nga may hinagiban.',
        12: 'Usa ka tawo nga walay hinungdan, usa ka tawo sa kasal-anan, Mao siya nga nagalakat nga may usa ka masukihong baba;',
        13: 'Nga nagapangidhat sa iyang mga mata, nga namulong uban sa iyang mga tiil, Nga nagabuhat ug mga ilhanan uban sa iyang mga tudlo;',
        14: 'Sa kang kinsang kasingkasing anaa ang pagkamasukihon, Nga nagalalang ug dautan sa kanunay, Nga nagapugas sa pagpakiglalis.',
        15: 'Busa ang iyang kalisdanan modangat sa hinanali; Sa usa ka hinanali siya mabungkag, ug nga niana walay arang ikatabang.',
        16: 'Adunay unom ka butang nga gidumtan ni Jehova; Oo, pito nga maoy dulumtanan niya:',
        17: 'Mapahitas-ong mga mata, usa ka dila nga bakakon, Ug mga kamot nga nag-ula sa dugo nga inocente;',
        18: 'Usa ka kasingkasing nga nagalalang sa dautang mga tinguha, Mga tiil nga matulin nga modalagan ngadto sa binilyako,',
        19: 'Usa ka bakakon nga saksi nga nagapamulong ug mga bakak, Ug kadto nga nagapugas sa pagkalalis sa mga kaigsoonan.',
        20: 'Anak ko, bantayi ang sugo sa imong amahan, Ug ayaw pagbiyai ang balaod sa imong inahan:',
        21: 'Bugkuson mo sila kanunay sa imong kasingkasing; Ibaligtos sila sa imong liog.',
        22: 'Sa diha nga ikaw magalakaw, kini magatultol kanimo; Sa diha nga ikaw matulog, kini magabantay kanimo; Ug sa diha nga ikaw mahigmata kini makigsulti kanimo.',
        23: 'Kay ang sugo maoy usa ka lamparahan; ug ang balaod maoy suga; Ug ang pagbadlong sa pahamatngon maoy dalan sa kinabuhi:',
        24: 'Sa pagpalikay kanimo gikan sa dautang babaye, Gikan sa pag-uloulo sa dila sa dumuloong.',
        25: 'Ayaw kaibug sa iyang kaanyag diha sa imong kasingkasing; Ni pabihag ikaw kaniya uban sa mga tabontabon sa iyang mga mata.',
        26: 'Kay tungod sa usa ka babaye nga bigaon ang usa ka tawo mataral lamang ngadto sa usa ka tipak nga tinapay; Ug ang babayeng mananapaw mangita alang sa bililhon nga kinabuhi.',
        27: 'Makadala ba ang usa ka tawo ug kalayo sa iyang sabakan, Ug ang iyang mga sapot dili ba masunog?',
        28: 'Kun makalakat ba ang usa ka tawo ibabaw sa mainit nga mga baga, Ug ang iyang mga tiil dili ba mapagtong?',
        29: 'Busa siya nga moadto sa asawa sa iyang isigkatawo; Bisan kinsa nga makapanghilabut kaniya dili gayud makagawas sa silot.',
        30: 'Ang mga tawo dili magatamay sa usa ka kawatan, kong siya mangawat Aron sa pagtagbaw sa iyang kaugalingon sa diha nga siya pagagutom:',
        31: 'Apan kong siya hidakpan, magauli siya sa pito ka pilo nga gidaghanon; Siya magahatag sa tanan niyang manggad sa iyang balay.',
        32: 'Siya nga makapanapaw sa usa ka babaye maoy tawong walay salabutan: Siya nagabuhat niini aron sa paglaglag sa iyang kaugalingong kalag.',
        33: 'Ang mga samad ug pagkawalay dungog mao ang iyang mamakuha; Ug ang iyang pagkawalay-ulaw dili na gayud mapapas',
        34: 'Kay ang pangabugho mao ang kapungot sa usa ka tawo; Ug siya dili mopasaylo sa adlaw sa pagpanimalus.',
        35: 'Siya dili motagad ug bisan unsang paglukat; Ni matagbaw siya bisan pa kong hatagan mo ug daghang mga gasa.',
    },
    7: {
        1: 'Anak ko, bantayi ang akong mga pulong, Ug tagoa ang akong mga sugo uban kanimo.',
        2: 'Bantayi ang akong mga sugo ug ikaw mabuhi; Ug ang akong balaod ingon sa tawo-tawo sa imong mata.',
        3: 'Ibugkos sila sa imong mga tudlo; Isulat mo sila ibabaw sa papan sa imong kasingkasing.',
        4: 'Pamulongan mo ang kaalam: Ikaw mao ang akong igsoon nga babaye; Ug tawga ang salabutan nga imong kauban nga babaye:',
        5: 'Aron sila magabantay kanimo gikan sa dumuloong babaye, Gikan sa dumuloong nga maga-ulo-ulo uban sa iyang mga pulong.',
        6: 'Kay sa tamboanan sa akong balay Ako milili sa akong rihas;',
        7: 'Ug ako nakatan-aw sa taliwala sa mga walay-pagtagad, Ako nakaila diha sa taliwala sa mga batan-on, Sa usa ka batan-on nga walay salabutan,',
        8: 'Miagi sa dalan haduol sa iyang likoanan; Ug siya mipadulong ngadto sa iyang balay,',
        9: 'Sa pagkasalumsom, sa pagkahapon sa adlaw, Sa pagkatungang gabii ug sa kangitngitan.',
        10: 'Ug, ania karon, may mitagbo kaniya nga usa ka babaye Sa pamisti sa usa ka babayeng bigaon, ug malimbongon sa kasingkasing.',
        11: '(Siya sabaan ug malimbongon; Ang iyang mga tiil dili mahimutang sa iyang balay:',
        12: 'Karon siya anaa sa kadalanan, unya sa halapad nga mga dapit, Ug magahubong sa tagsatagsa ka likoanan).',
        13: 'Busa iyang hidakpan siya, ug gihagkan siya, Ug uban sa usa ka magahing nawong siya miingon kaniya:',
        14: 'Mga halad sa halad-sa-pakigdait maoy ania kanako; Niining adlawa gituman ko ang akong mga panaad.',
        15: 'Sa ingon niana ako milakat aron sa pagpakigtagbo kanimo, Sa masingkamoton nga pagpangita sa imong nawong, ug hikaplagan ko ikaw.',
        16: 'Gibuklad ko na sa akong higdaanan ang mga habol nga binuldahan, Sa ginihay nga mga panapton nga hinabol sa Egipto.',
        17: 'Gipahumotan ko na ang akong higdaanan. Sa mirra, aloes ug sinamomo;',
        18: 'Umari ka, maghubog kita sa gugma hangtud sa pagkabuntag; Managlipay kita sa atong kaugalingon sa mga gugma.',
        19: 'Kay ang akong lalake wala sa balay; Siya atua sa halayong panaw:',
        20: 'Siya nagdala ug usa ka puntil nga salapi uban kaniya; Siya mopauli sa balay sa motakdul na ang bulan.',
        21: 'Pinaagi sa iyang madanihon nga pakigpulong siya nakalukmay kaniya; Uban sa ulo-ulo sa iyang mga ngabil napugos siya sa pagnunot kaniya,',
        22: 'Siya misunod kaniya sa walay langan, Ingon sa usa ka vaca nga nagapadulong ngadto sa ihawan, Kun maingon sa usa nga anaa sa mga talikala aron sa pagtul-id sa mga buang;',
        23: 'Hangtud nga ang usa ka udyong molagbas sa iyang atay, Ingon sa usa ka langgam nga nagdali ngadto sa lit-ag, Ug wala manghibalo nga kana alang sa iyang kinabuhi.',
        24: 'Busa karon, mga anak ko, patalinghug kamo kanako, Ug matngoni ninyo ang mga pulong sa akong baba.',
        25: 'Ayaw pagpakilinga ang imong kasingkasing ngadto sa iyang mga dalan; Ayaw pagpasalaag ngadto sa iyang mga alagianan:',
        26: 'Kay siya nagapabutalid sa daghang mga samaran: Oo, ang tanan sa iyang gipamatay usa na ka dakung panon.',
        27: 'Ang iyang balay maoy dalan ngadto sa Sheol, Nga nagalugsong ngadto sa mga lawak sa kamatayon.',
    },
    8: {
        1: 'Wala ba magsinggit ang kaalam, Ug ang pagsabut magapagula sa iyang tingog?',
        2: 'Sa kinatumyan sa hatag-as nga mga dapit haduol sa dalan, Diin ang mga alagianan nanagkatagbo siya nagatindog;',
        3: 'Tupad sa mga ganghaan, dapit sa pagsulod mo ngadto sa ciudad, Diha sa dapit sa pagsulod mo sa mga pultahan, siya magasinggit sa makusog:',
        4: 'Kaninyo, Oh mga tawo, ako nagatawag; Ug ang akong tingog maoy alang sa mga anak nga lalake sa mga tawo.',
        5: 'Oh kamo nga mga walay-pagtagad, sabta ang pagpili-sa-maayo; Ug, kamong mga buang, pagmasinabtanon kamo sa inyong kasingkasing.',
        6: 'Pamati, kay ako mamulong sa labing maayo nga mga butang; Ug ang pagbungat sa akong mga ngabil mogula ang mga matarung butang.',
        7: 'Kay ang akong baba magasulti sa kamatuoran; Ug ang kadautan maoy usa ka dulumtanan sa akong mga ngabil.',
        8: 'Ang tanang mga pulong sa akong baba mga pagkamatarung man; Walay bisan unsa nga baliko ni balit-ad diha kanila.',
        9: 'Silang tanan matin-aw alang kaniya nga makasabut, Ug matarung alang kanila nga nakakaplag sa kahibalo.',
        10: 'Dawata ang akong pagpahamatngon, ug ayaw ang salapi; Ug ang kinaadman kay sa piniling bulawan.',
        11: 'Kay ang kaalam labi pang maayo kay sa mga rubi; Ug ang tanang mga butang nga pagatinguhaon dili ikagtanding niana.',
        12: 'Ako nga kaalam naghimo sa kabuotan nga maoy akong puloyanan. Ug nagapangita sa kahibalo ug sa pagpili-sa-maayo.',
        13: 'Ang pagkahadlok kang Jehova maoy pagdumot sa dautan: Ang pagkagarboso, ug pagkamapahitas-on, ug ang dautan nga dalan, Ug ang mabinalit-aron nga baba maoy akong ginadumtan.',
        14: 'Ang pagpakitambag maoy ako, ug kahalalum sa kahibalo: Ako mao man ang pagsabut; aduna akoy kagahum.',
        15: 'Pinaagi kanako ang mga hari nanaghari, Ug ang mga principe nanaghatag sa justicia.',
        16: 'Pinaagi kanako ang mga principe nanagpamunoan, Ug ang mga harianon, bisan ang tanang mga maghuhukom sa yuta.',
        17: 'Ako nahagugma kanila nga nahagugma kanako; Ug kadtong nagasingkamot sa pagpangita kanako, makakaplag kanako.',
        18: 'Mga bahandi ug kadungganan maoy ania kanako; Oo, ang katigayonan nga molungtad ug ang pagkamatarung',
        19: 'Ang akong bunga labi pang maayo kay sa bulawan, oo, bisan pa kay sa fino nga bulawan; Ug ang akong abut kay sa piniling salapi.',
        20: 'Ako nagalakat sa dalan sa pagkamatarung, Sa kinataliwad-an sa alagianan sa katarungan;',
        21: 'Aron nga ako makapasunod niadtong nahagugma kanako ug manggad, Ug nga mapuno ko ang ilang mga panudlanan.',
        22: 'Si Jehova nagbaton kanako sa sinugdan sa iyang dalan, Una pa sa iyang mga buhat kanhi.',
        23: 'Ako gipahamutang sa itaas gikan pa sa walay katapusan sukad sa sinugdan, Sa wala pa ang yuta.',
        24: 'Sa diha nga wala pay kahiladman, ako nahimugso na, Sa diha nga wala pay mga tubod nga madagayaon sa tubig.',
        25: 'Sa wala pa mapahimutang ang mga bukid, Sa wala pa ang kabungturan ako nahimugso na;',
        26: 'Samtang nga wala pa niya mabuhat ang yuta, ni ang kapatagan, Ni ang sinugdan sa abug sa kalibutan.',
        27: 'Sa diha nga gitukod niya ang kalangitan didto na ako: Sa gipahamutang niya ang usa ka lingin ibabaw sa nawong sa kahilad-man,',
        28: 'Sa diha nga gihimo niyang malig-on ang kalangitan sa kahitas-an, Sa diha nga ang mga tuboran sa kahiladman nahimong mabaskog,',
        29: 'Sa diha nga gihatag niya sa dagat ang iyang utlanan, Nga ang mga tubig dili magalapas sa iyang sugo, Sa diha nga iyang gilaraw ang mga patukoranan sa yuta;',
        30: 'Unya ako didto tupad kaniya, ingon sa usa ka batid nga magbubuhat; Ug ako sa matag-adlaw maoy kahimuot niya, Nagakalipay sa kanunay sa iyang atubangan,',
        31: 'Nagakalipay sa iyang puloy-anang yuta; Ug ang akong kahimuot didto uban sa mga anak sa mga tawo.',
        32: 'Busa karon, mga anak ko, patalinghug kamo kanako; Kay bulahan kadto sila nga nagabantay sa akong mga dalan.',
        33: 'Pamatia ang pahamatngon, ug pagmanggialamon, Ug ayaw kini pag-isalikway.',
        34: 'Bulahan ang tawo nga mamati kanako, Nga magabantay matag-adlaw sa akong mga ganghaan, Nga magahulat diha sa mga haligi sa akong mga pultahan.',
        35: 'Kay bisan kinsa kadto nga makakaplag kanako makakaplag ug kinabuhi, Ug makabaton sa kalooy kang Jehova.',
        36: 'Apan siya nga makasala batok kanako makasala sa iyang kaugalingong kalag: (8-37) Silang tanan nga managdumot kanako mahagugma sa kamatayon.',
    },
    9: {
        1: 'Ang kaalam nagtukod sa iyang balay; Iyang gihinloan ang iyang pito ka mga haligi:',
        2: 'Siya nagpatay sa iyang mga mananap; siya nagsagol sa iyang vino, Siya usab nag-andam sa iyang lamesa:',
        3: 'Siya nagpalakat sa iyang kadalagahan; Siya nagsinggit ibabaw sa labing kinatas-ang mga dapit sa ciudad:',
        4: 'Bisan kinsa kadto nga walay-pagtagad, paatubanga siya dinhi: Mahatungod niadtong walay salabutan, siya nagaingon kaniya:',
        5: 'Umari, kumaon kamo sa akong tinapay, Ug uminum kamo sa vino nga akong gisagol.',
        6: 'Biyai, kamo nga mga walay-pagtagad, ug kamo mabuhi; Ug lumakat sa dalan sa pagsabut;',
        7: 'Kadtong magabadlong sa usa ka mayubiton makadawat sa iyang kaugalingon ug pulong sa panamastamas; Ug kadtong magasaway sa usa ka tawo nga dautan makakuha sa iyang kaugalingon ug usa ka buling.',
        8: 'Ayaw pagbadlonga ang usa ka mayubiton, tingali unya siya magadumot kanimo: Badlonga ang usa ka tawong manggialamon, ug siya mahagugma kanimo.',
        9: 'Hatagi ug pahamatngon ang usa ka tawong manggialamon, ug siya magamaalamon pa sa pagsamot: Tudloi ang matarung nga tawo, ug siya magadugang pa sa kinaadman.',
        10: 'Ang pagkahadlok kang Jehova maoy sinugdan sa kaalam; Ug ang kahibalo niadtong Balaan mao ang pagsabut.',
        11: 'Kay pinaagi kanako ang imong mga adlaw pagapilo-piloon, Ug ang mga tuig sa imong kinabuhi pagapadaghanon.',
        12: 'Kong ikaw manggialamon, ikaw manggialamon sa imong kaugalingon; Ug kong ikaw magayubit, ikaw ra ang magadala niini.',
        13: 'Ang buang-buang nga babaye sabaan man; Siya walay-pagtagad ug walay hibangkaagan.',
        14: 'Ug siya magalingkod sa pultahan sa iyang balay, Ibabaw sa usa ka lingkoranan diha sa usa ka hataas nga dapit sa ciudad,',
        15: 'Sa pagsangpit niadtong managpangagi, Nga manglakat sa matul-id sa ilang mga dalan:',
        16: 'Bisan kinsa nga walay-pagtagad, pahapita siya nganhi; Ug alang kaniya nga walay salabutan, siya moingon kaniya:',
        17: 'Matam-is ang kinawat nga mga tubig, Ug lamian ang tinapay nga pagakan-on sa tago.',
        18: 'Apan siya wala mahibalo nga ang mga nangamatay atua didto; Nga ang iyang mga dumudu-aw anaa sa mga kahiladman sa Sheol.',
    },
    10: {
        1: 'Ang mga proverbio ni Salomon. Ang usa ka anak nga manggialamon maoy kalipay sa iyang amahan; Apan ang usa ka anak nga buang-buang maoy kaguol sa iyang inahan.',
        2: 'Ang mga bahandi sa kadautan walay kapuslanan; Apan ang pagkamatarung magaluwas gikan sa kamatayon.',
        3: 'Si Jehova dili motugot sa kalag sa tawong matarung nga magutom; Apan ipahilayo niya ang tinguha sa dautan.',
        4: 'Mahimong kabus ang magabuhat uban ang usa ka kamot nga tapulan; Apan ang kamot sa makugihon makapahimong adunahan.',
        5: 'Kadtong nagaani panahon sa tinginit maoy usa ka manggialamon nga anak; Apan kadtong nagakatulog sa tingani maoy usa ka anak nga nagapakaulaw.',
        6: 'Ang mga panalangin maoy anaa sa ibabaw sa ulo sa matarung; Apan ang pagpanlupig nagatabon sa baba sa dautan.',
        7: 'Ang handumanan sa matarung maoy bulahan; Apan ang ngalan sa dautan madunot.',
        8: 'Ang manggialamon sa kasingkasing magadawat ug mga sugo; Apan ang usa ka buang-buang nga witwitan mahulog sa kagul-anan.',
        9: 'Kadtong nagalakat sa pagkamatul-id nagalakat sa kasigurohan; Apan kadtong nagamasukihon sa iyang mga dalan mahibaloan.',
        10: 'Kadtong nagapangilo sa mata nagahatag ug kasubo; Apan ang usa ka buang-buang nga witwitan mahulog sa kagul-anan.',
        11: 'Ang baba sa matarung maoy usa ka tuburan sa kinabuhi; Apan ang pagpanlupig nagatabon sa baba sa dautan.',
        12: 'Ang pagdumot nagapapukaw sa mga kasamok; Apan ang gugma nagatabon sa tanang mga kalapasan.',
        13: 'Diha sa mga ngabil niadtong adunay panimuot hikaplagan ang kaalam: Apan ang usa ka bunal alang sa likod niadtong walay pagsabut.',
        14: 'Ang mga tawong manggialamon nagatigum ug kahibalo; Apan ang baba sa buang-buang mao ang usa ka pagkalaglag karon.',
        15: 'Ang bahandi sa tawong adunahan mao ang iyang malig-on nga ciudad; Ang pagkalaglag sa mga kabus mao ang ilang pagkakabus.',
        16: 'Ang pagpamoo sa tawong matarung nagapadulong ngadto sa kinabuhi; Ang abut sa tawong dautan, ngadto sa pagpakasala.',
        17: 'Anaa sa dalan sa kinabuhi kadtong mamati sa pagbadlong; Apan kadtong nagasalikway sa pagbadlong anaa sa kasaypanan.',
        18: 'Kadtong nagatago sa pagdumot adunay bakakon nga mga ngabil; Ug kadtong nagapamulong us usa ka butang-butang maoy usa ka buang.',
        19: 'Diha sa daghang mga pulong dili mawad-an sa kalapasan; Apan kadtong nagapugong sa iyang mga ngabil nagabuhat sa manggialamon gayud.',
        20: 'Ang dila sa tawong matarung ingon sa piniling salapi: Ang kasingkasing sa tawong dautan diyutay ra ug bili.',
        21: 'Ang mga ngabil sa matarung magapakaon ug daghan; Apan ang buang-buang mamatay tungod sa pagkakulang ug salabutan,',
        22: 'Ang panalangin ni Jehova, nagapadato kini; Ug siya wala magadugang ug kasubo niana.',
        23: 'Maoy usa ka lingaw-lingaw sa usa ka buang ang pagbuhat ug kadautan; Ug maingon niini ang kaalam alang sa usa ka tawo nga masinabuton,',
        24: 'Ang kahadlok sa tawong dautan, kini modangat sa ibabaw niya; Ug ang tinguha sa tawong matarung igatugot man.',
        25: 'Sa paglabay sa alimpulos ang dautan mahanaw; Apan ang matarung maoy usa ka patukoranan nga walay katapusan.',
        26: 'Maingon sa suka nga alang sa mga ngipon, ug sa aso nga alang sa mga mata, Mao man usab ang tapulan alang niadtong nagasugo kaniya.',
        27: 'Ang pagkahadlok kang Jehova nagapalugway sa mga adlaw; Apan ang mga tuig sa dautan pagahamub-on.',
        28: 'Ang paglaum sa matarung mao ang kalipay; Apan ang gipaabut niadtong dautan mawagtang.',
        29: 'Ang dalan ni Jehova maoy usa ka malig-ong salipdanan sa tawong matul-id; Apan kini maoy usa ka pagkalaglag sa mga mamumuhat sa kasal-anan.',
        30: 'Ang matarung dili gayud matarug; Apan ang dautan dili magadayon sa yuta.',
        31: 'Ang baba sa matarung magabunga ug kaalam; Apan ang dila nga masukihon pagaputlon.',
        32: 'Ang mga ngabil sa matarung mahibalo sa angay nga pagadawaton; Apan ang baba sa dautan nagapamulong sa pagkamasukihon.',
    },
    11: {
        1: 'Ang usa ka timbangan nga limbongan maoy usa ka dulumtanan kang Jehova; Apan ang matarung nga bato sa timbangan maoy iyang kalipay.',
        2: 'Kong ang pagkamapahitas-on moabut, nan modangat unya ang kaulaw; Apan sa mapinaubsanon mao ang kaalam.',
        3: 'Ang kaligdong sa matul-id maoy magamando kanila; Apan ang pagkamasukihon sa maluibon maoy malaglag kanila.',
        4: 'Ang kadato dili magapulos adlaw sa kaligutgut; Apan ang pagkamatarung magaluwas sa tawo gikan sa kamatayon.',
        5: 'Ang pagkamatarung sa tawong hingpit maoy magamando sa iyang dalan; Apan ang dautan mahulog pinaagi sa iyang kaugalingong pagkadautan.',
        6: 'Ang pagkamatarung sa tawong matul-id maoy magaluwas kanila; Apan ang maluibon malit-ag sa ilang kaugalingong kasal-anan.',
        7: 'Kong ang dautang tawo mamatay, ang iyang ginapaabut mahanaw; Ug ang paglaum sa kasal-anan mahanaw;',
        8: 'Ang tawong matarung maluwas gikan sa kasamok; Ug ang dautan moabut ilis kaniya.',
        9: 'Pinaagi sa iyang baba ang tawo nga dili-diosnon magalaglag sa iyang isigkatawo; Apan pinaagi sa kahibalo ang tawong matarung mamaluwas.',
        10: 'Kong maayo ang paglakat sa mga matarung, ang ciudad magakalipay; Ug sa mawala na ang dautan, adunay panaghugyaw.',
        11: 'Tungod sa panalangin sa tawong matul-id ang ciudad igatuboy sa kahitas-an; Apan kini magun-ob tungod sa baba sa dautan.',
        12: 'Kadtong nagatamay sa iyang isigkatawo walay kaalam; Apan ang tawo nga may salabutan nagahilum.',
        13: 'Kadtong nagasuroy-suroy ingon sa usa ka tabian nagabutyag sa mga tinago; Apan kadtong may pagkamatinumanon sa espiritu nagatago sa usa ka butang.',
        14: 'Diin walay maalamon nga pagmando, ang katawohan mangapukan; Apan diha sa panon sa mga magtatambag adunay kasigurohan.',
        15: 'Kadtong maoy pasalig alang sa usa ka dumuloong magaantus ug kalisud; Apan kadtong magadumot sa pagkapasalig anaa sa kasigurohan.',
        16: 'Ang usa ka maloloy-ong babaye makabaton ug kadungganan; Ug ang tawo nga malupigon makabaton ug mga bahandi.',
        17: 'Ang tawo nga maloloy-on naga buhat ug maayo sa iyang kaugalingong kalag; Apan kadtong tigdagmal nagasakit sa iyang kaugalingong unod.',
        18: 'Ang mga dautan nagadawat sa limbong nga mga suhol; Apan kadtong nagapugas ug pagkamatarung may balus nga siguro.',
        19: 'Kadtong kanunay sa pagkamatarung makadangat ngadto sa kinabuhi; Ug kadtong nagapangita sa dautan nagahimo niana alang sa iyang kaugalingong kamatayon.',
        20: 'Kadtong masukihon diha sa kasingkasing maoy usa ka dulumtanan kang Jehova; Apan ang mga mahingpit sa ilang dalan maoy iyang kalipay.',
        21: 'Bisan ang kamot madugtong sa kamot, ang dautang tawo dili makagawas sa silot; Apan ang kaliwat sa mga matarung pagaluwason.',
        22: 'Maingon sa usa ka singsing nga bulawan diha sa simod sa baboy, Mao man ang usa ka maanyag nga babaye nga walay kabuot.',
        23: 'Ang tinguha sa tawong matarung mao lamang ang maayo; Apan ang paalabuton sa dautan mao ang kaligutgut.',
        24: 'Adunay nagasabulak ug nagadugang pa gayud; Ug adunay nagatipig nga labi pa kay sa gikinahanglan, apan kini nagadugang hinoon sa kawalad-on.',
        25: 'Ang kalag nga mahinatagon mahimong matambok; Ug kadtong nagabisibis pagabisibisan usab sa iyang kaugalingon.',
        26: 'Kadtong nagahikaw sa makaon, pagatunglohon siya sa katawohan; Apan ang panalangin anaa sa ibabaw sa ulo niya nga nagabaligya niini.',
        27: 'Kadtong nagapangita sa masingkamoton gayud sa maayo nagapangita ug kalooy; Apan kadtong nagapangita ug kadautan, kini modangat kaniya.',
        28: 'Kadtong nagasalig sa iyang mga bahandi mapukan; Apan ang matarung magamauswagon ingon sa lunhaw nga dahon.',
        29: 'Kadtong nagasamok sa iyang kaugalingong balay magapanunod sa hangin; Ug ang buang mahimong ulipon sa manggialamon ug kasingkasing.',
        30: 'Ang bunga sa matarung maoy usa ka kahoy sa kinabuhi; Ug kadtong manggialamon makadani ug mga kalag.',
        31: 'Ania karon, ang matarung pagabalusan dinhi sa yuta; Labi pa gayud ang dautan ug ang makasasala!',
    },
    12: {
        1: 'Bisan kinsa nga mahagugma sa pagsaway mahagugma sa kahibalo; Apan kadtong magadumot sa pagbadlong mananapon man.',
        2: 'Ang usa ka maayong tawo makabaton ug kalooy kang Jehova; Apan ang usa ka tawo nga dautan ug mga lalang iyang pagasilotan.',
        3: 'Ang usa ka tawo dili malig-on pinaagi sa kadautan; Apan ang gamut sa matarung dili matarug.',
        4: 'Ang usa ka babaye nga may katakus maoy purong-purong sa iyang bana; Apan kadtong nagahimo ug pagpakaulaw maingon sa pagkamadunoton sa iyang mga bukog.',
        5: 'Ang mga hunahuna sa matarung lonlon mga matarung; Apan ang tambag sa dautan lonlon mga limbong.',
        6: 'Ang mga pulong sa dautan maoy mga pagbanhig alang sa dugo; Apan ang baba sa matul-id magaluwas kanila.',
        7: 'Ang tawong dautan ginapukan, ug mangahanaw; Apan ang balay sa matarung molungtad.',
        8: 'Ang usa ka tawo pagadayegon sumala sa iyang kaalam; Apan kadtong may kasingkasing nga masukihon pagatamayon.',
        9: 'Maayo pa kadtong gimahal ug diyutay, ug may usa ka sulogoon, Kay niadtong nagapasidungog sa iyang kaugalingon, ug nakulangan sa makaon.',
        10: 'Ang usa ka tawo nga matarung nagamahal sa kinabuhi sa iyang mananap; Apan ang malomong mga kalooy sa tawong dautan mao ang kabangis.',
        11: 'Kadtong nagauma sa iyang yuta makabaton ug daghang makaon; Apan kadtong nagasunod sa mga tawo nga walay hinungdan walay salabutan.',
        12: 'Ang dautan nagatinguha sa pukot sa dautan nga mga tawo; Apan ang gamut sa matarung magahatag ug bunga.',
        13: 'Sa pagkamalapason sa mga ngabil maoy usa ka lit-ag sa dautang tawo; Apan ang matarung mahigawas gikan sa kasamok.',
        14: 'Ang usa ka tawo mabusog sa maayo tungod sa bunga sa iyang baba; Ug ang mga buhat sa mga kamot sa usa ka tawo igahatag kaniya.',
        15: 'Ang dalan sa usa ka buang matarung man sa iyang kaugalingong mga mata; Apan kadtong manggialamon nagapamati ug tambag.',
        16: 'Ang kasuko sa usa ka buang mahibaloan dayon sa dayag; Apan ang usa ka mabinantayong tawo nagabaton ug kaulaw.',
        17: 'Kadtong nagapamulong sa kamatuoran nagapakita ug pagkamatarung; Apan ang usa ka bakakon nga saksi nagapakita ug limbong.',
        18: 'Adunay magapamulong sa hinanali sama sa mga paglagbas sa usa ka espada; Apan ang dila sa manggialamon makaayo.',
        19: 'Ang ngabil sa kamatuoran pagalig-onon sa walay katapusan; Apan ang usa ka bakakong dila umalagi lamang.',
        20: 'Ang paglimbong maoy anaa sa kasingkasing kanila nga nagamugna ug dautan; Apan sa mga magtatambag sa pakigdait mao ang kalipay.',
        21: 'Walay kadaut nga mahitabo sa tawong matarung; Apan ang dautan pagapun-on sa q2 kadautan.',
        22: 'Ang bakakon nga mga ngabil du lumtanan kang Jehova; Apan kadtong nagabuhat sa kamatuoran maoy iyang kalipay.',
        23: 'Ang usa ka tawong buotan nagabaton ug kahibalo; Apan ang kasingkasing sa mga buang nagabutyag sa kabuangan.',
        24: 'Ang kamot sa makugihon magadala ug pagbulot-an; Apan ang tapulan igabutang sa usa ka mabug-at nga bulohaton.',
        25: 'Ang kaguol nga anaa sa kasingkasing sa usa ka tawo maoy makapatikuko kaniya; Apan ang usa ka maayong pulong makapahimo niini nga malipayon.',
        26: 'Ang matarung maoy usa ka magtutultol sa iyang silingan; Apan ang dalan sa dautan maoy makapasalaag kanila.',
        27: 'Ang tawong tapulan dili makaasal sa iyang inayaman; Apan ang bililhong manggad sa mga tawo mao ang pagkamakugihon.',
        28: 'Diha sa dalan sa pagkamatarung mao ang kinabuhi; Ug diha sa alagianan niana walay kamatayon.',
    },
    13: {
        1: 'Ang usa ka manggialamon nga anak mamati sa pahamatngon sa iyang amahan; Apan ang usa ka mayubiton dili mamati sa pagbadlong.',
        2: 'Ang tawo magakaon ug maayo pinaagi sa bunga sa iyang baba; Apan ang kalag sa maluibon magakaon sa pagpanlupig.',
        3: 'Kadtong nagabantay sa iyang baba nagamatngon sa iyang kinabuhi; Apan kadtong nagawalis sa halapad gayud sa iyang mga ngabil adunay kadautan.',
        4: 'Ang kalag sa tapulan nagatinguha, ug siya walay bisan unsa; Apan ang kalag sa makugihon mahimong matambok,',
        5: 'Ang usa ka tawo nga matarung magadumot sa pagpamakak; Apan ang usa ka dautang tawo makaluod, ug modangat sa kaulawon.',
        6: 'Ang pagkamatarung nagabantay niadtong matul-id sa iyang dalan; Apan ang kadautan mopukan sa makasasala.',
        7: 'Adunay magapakadato sa iyang kaugalingon, apan siya walay bisan unsa; Adunay magapakakabus sa iyang kaugalingon, apan siya may dakung katigayonan.',
        8: 'Ang lukat sa usa ka tawo sa iyang kinabuhi mao ang iyang mga bahandi; Apan ang kabus dili mamati sa bisan unsay paghulga.',
        9: 'Ang kahayag sa matarung malipayon; Apan ang lamparahan sa dautan pagapalongon.',
        10: 'Tungod sa pagkamapahitas-on modangat lamang ang panagkabingkil; Apan sa maayong tinambagan mao ang kaalam.',
        11: 'Ang katigayonan nga maani sa kakawangan magakahanaw; Apan kadtong nagatigum pinaagi sa pagpamoo adunay kauswagan.',
        12: 'Ang paglaum nga makulangan makapadaut sa kasingkasing; Apan kong ang tinguha modangat, kana mao ang usa ka kahoy sa kinabuhi.',
        13: 'Bisan kinsa nga magatamay sa pulong magadala ug kadaut sa iyang kaugalingon; Apan kadtong mahadlok sa kasugoan pagabalusan.',
        14: 'Ang balaod sa manggialamon maoy usa ka tuburan sa kinabuhi, Aron nga ang usa makalikay gikan sa mga lit-ag sa kamatayon.',
        15: 'Ang maayong pagsabut mohatag ug kalooy; Apan ang dalan sa malapason maoy malisud.',
        16: 'Ang tagsatagsa ka buotan nga tawo magabuhat uban sa kahibalo; Apan ang buang magapagarbo sa iyang binuang.',
        17: 'Ang usa ka dautan nga sinugo mahulog ngadto sa kadaut; Apan ang usa ka matinumanon nga sinaligan maoy makaayo.',
        18: 'Ang kawalad-on ug kaulaw modangat kaniya nga magadumili sa pagsaway; Apan kadtong manumbaling sa pagbadlong pagapasidunggan.',
        19: 'Ang tinguha nga natuman maoy katam-is sa kalag; Apan maoy usa ka dulumtanan sa mga buang ang pagbiya gikan sa dautan.',
        20: 'Lakat uban sa tawong manggialamon, ug ikaw mahimong manggialamon; Apan ang kauban sa mga buang magaantus tungod niana.',
        21: 'Ang dautan nagalutos sa mga makasasala; Apan ang matarung pagabalusan uban sa maayo.',
        22: 'Ang usa ka maayong tawo magabilin ug usa ka panulondon alang sa mga anak sa iyang mga anak; Ug ang katigayonan sa mga makasasala gitigum alang sa mga matarung.',
        23: 'Daghan ang makaon diha sa binaulan nga yuta sa kabus; Apan adunay pagalaglagon tungod sa pagkawalay-justicia.',
        24: 'Kadtong nagahawid sa iyang bunal nagadumot sa iyang anak; Apan kadtong nahagugma kaniya magacastigo kaniya sa matag-panahon.',
        25: 'Ang matarung magakaon aron sa pagpabusog sa iyang kalag; Apan ang tiyan sa mga dautan pagagutomon.',
    },
    14: {
        1: 'Ang tagsatagsa ka manggialamon nga babaye magatukod sa iyang balay; Apan ang buangbuang magaguba niana uban sa iyang mga kamot.',
        2: 'Kadtong nagalakat sa iyang pagkatul-id nahadlok kang Jehova; Apan kadtong sukwahi sa iyang dalan nagatamay kaniya.',
        3: 'Diha sa baba sa buangbuang mao ang usa ka bunal alang sa iyang pagkamapahitas-on; Apan ang mga ngabil sa manggialamon magabantay kanila.',
        4: 'Sa dapit diin walay mga vaca, ang pasungan mahinlo; Apan ang dakung abut pinaagi sa kusog sa vaca.',
        5: 'Ang usa ka matinumanon nga saksi dili mobakak; Apan ang bakakon nga saksi magapamulong ug mga bakak.',
        6: 'Ang usa ka mayubiton magapangita sa kaalam ug dilimakakaplag niini; Apan ang kahibalo masayon alang kaniya nga may salabutan.',
        7: 'Lakaw ngadto sa atubangan sa usa ka tawong buangbuang, Ug ikaw dili makakaplag diha kaniya sa mga ngabil sa kahibalo.',
        8: 'Ang kaalam sa buotan mao ang pagsabut sa iyang dalan; Apan ang binuang sa mga buangbuang mao ang paglimbong.',
        9: 'Ang mga buang magatiaw-tiaw lamang sa halad-tungod-sa-sala; Apan sa taliwala sa mga matarung adunay maayong kabubut-on.',
        10: 'Ang kasingkasing mahibalo sa iyang kaugalingong kapaitan; Ug walay usa ka dumuloong nga moambit sa kalipay niini.',
        11: 'Ang balay sa tawong dautan pagagun-obon; Apan ang balong-balong sa matarung pagapauswagon.',
        12: 'Adunay usa ka dalan nga daw matarung alang sa usa ka tawo; Apan ang katapusan niana mao ang mga dalan sa kamatayon.',
        13: 'Bisan diha sa pagkatawa ang kasingkasing magamasulub-on; Ug ang katapusan sa kalipay mao ang kagul-anan.',
        14: 'Ang nagabalik sa pagpakasala sa kasingkasing pagapun-on uban sa iyang kaugalingong mga paagi; Ug ang usa ka maayong tawo matagbaw gikan sa iyang kaugalingon.',
        15: 'Ang walay-pagtagad motoo sa tagsatagsa ka pulong; Apan ang mabinantayon nga tawo magatan-aw pag-ayo sa iyang paglakaw.',
        16: 'Ang usa ka tawong manggialamon mahadlok, ug magapahilayo gikan sa dautan; Apan ang buang mapangahason sa iyang kaugalingon nga may pagdaut ug siya masaligon.',
        17: 'Siya nga dili masuko magahimo sa kabuangan; Ug ang usa ka tawo nga dautan ug mga paagi ginadumtan.',
        18: 'Ang walay-pagtagad makapanunod sa binuang; Apan ang mga buotan pagapurongpurongan sa kahibalo.',
        19: 'Ang tawong dautan moyukbo sa atubangan sa maayo; Ug ang dautan, diha sa mga ganghaan sa matarung.',
        20: 'Ang kabus ginadumtan bisan sa iyang kaugalingong silingan; Apan ang dato may daghang mga higala.',
        21: 'Kadtong nagatamay sa iyang isigkatawo nagapakasala; Apan kadtong may kalooy sa ka bus, malipayon siya.',
        22: 'Wala ba mangasayup kadtong nagamugna ug dautan? Apan ang puangod ug kamatuoran anaa kanila nga nagamugna ug maayo.',
        23: 'Diha sa tanang buhat adunay bunga; Apan ang sulti sa mga ngabil nagapadulong lamang ngadto sa kawalad-on nga tuman.',
        24: 'Ang purongpurong sa mga manggialamon mao ang ilang mga bahandi; Apan ang binuang sa mga buang mao lamang ang kabuangan.',
        25: 'Ang matuod nga saksi nagaluwas ug mga kalag; Apan kadtong nagapamulong sa kabakakan nagalimbong.',
        26: 'Diha sa pagkahadlok kang Jehova mao ang malig-on nga pagsalig; Ug ang iyang mga anak adunay usa ka dapit nga dalangpanan.',
        27: 'Ang pagkahadlok kang Jehova maoy usa ka tuburan sa kinabuhi, Aron nga ang tawo makalikay gikan sa mga lit-ag sa kamatayon.',
        28: 'Diha sa panon sa katawohan anaa ang himaya sa hari; Apan diha sa kawalad-on sa katawohan anaa ang kalaglagan sa principe.',
        29: 'Kadtong mahinay nga masuko may dakung salabutan; Apan kadtong madali-dalion sa espiritu nagabayaw sa kabuangan.',
        30: 'Ang usa ka malinawong kasingkasing maoy kinabuhi sa unod; Apan ang kasina mao ang pagkadunot sa kabukogan.',
        31: 'Kadtong nagadagmal sa kabus nagatamay sa iyang Magbubuhat; Apan kadtong may kalooy sa hangul nagatahud kaniya,',
        32: 'Ang dautan giunlod ngadto sa kahiladman tungod sa iyang buhat nga dautan; Apan ang matarung may usa ka dalangpanan sa iyang kamatayon.',
        33: 'Ang kaalam magapuyo diha sa kasingkasing niadtong may salabutan; Apan kadtong anaa sa sulod sa mga buang mapadayag sa iyang kaugalingon.',
        34: 'Ang pagkamatarung nagabayaw sa usa ka nasud; Apan ang sala maoy usa ka kaulawan sa bisan unsang katawohan.',
        35: 'Ang kalooy sa hari anaa sa usa ka sulogoon nga nagabuhat sa pagkamaalamon; Apan ang iyang kaligutgut anaa batok niadtong nagapakaulaw.',
    },
    15: {
        1: 'Ang tubag nga malomo makapahupay sa kapungot; Apan ang pulong nga mahait makapapukaw sa kasuko.',
        2: 'Ang dila sa manggialamon sa matul-id nagapamulong ug kahibalo; Apan ang baba sa mga buang nagabubo sa kabuangan.',
        3: 'Ang mga mata ni Jehova anaa sa tanang dapit, Nga nagabantay ibabaw sa dautan ug sa maayo.',
        4: 'Ang dila nga mahuyo maoy usa ka kahoy sa kinabuhi; Apan ang pagkasukwahi niana maoy pagkabungkag sa espiritu.',
        5: 'Ang usa ka buang magatamay sa pagsaway sa iyang amahan; Apan kadtong nagatagad sa pagbadlong nagapakita sa pagkabuotan.',
        6: 'Diha sa balay sa tawong matarung adunay daghang bahandi; Apan diha sa mga abut sa tawong dautan anaa ang kasamok.',
        7: 'Ang mga ngabil sa manggialamon nagabutyag ug kahibalo; Apan ang kasingkasing sa buangbuang dili magabuhat sa ingon.',
        8: 'Ang halad sa tawong dautan maoy usa ka dulumtanan kang Jehova; Apan ang pag-ampo sa tawong matul-id maoy iyang kalipay.',
        9: 'Ang dalan sa dautan maoy usa ka dulumtanan kang Jehova; Apan iyang gihigugma kadtong nagasunod sa pagkamatarung.',
        10: 'Adunay mapait nga pagsaway alang niadtong mibulag sa dalan; Ug kadtong nagadumot sa pagbadlong mamatay man.',
        11: 'Ang Sheol ug ang Pagkalaglag anaa sa atubangan ni Jehova; Nan daw unsa pa ang paglabaw sa mga kasingkasing sa mga anak sa mga tawo!',
        12: 'Ang usa ka mayubiton dili mahagugma nga pagabadlongon; Siya dili moadto sa pakigtipon sa manggialamon.',
        13: 'Ang malipayong kasingkasing nagapadayag sa usa ka masayag nga panagway; Apan tungod sa kasubo sa kasingkasing ang espiritu mamaluya.',
        14: 'Ang kasingkasing niadtong may salabutan nagapangita ug kahibalo; Apan ang baba sa mga buang nagakaon sa mga binuang.',
        15: 'Ang tanang mga adlaw sa mga sinakit mga kadaut man; Apan kadtong adunay malipayong kasingkasing may kombira sa kanunay.',
        16: 'Maayo pa ang diyutay nga inubanan sa pagkahadlok kang Jehova, Kay sa dakung bahandi ug inubanan sa kasamok.',
        17: 'Maayo pa ang usa ka paniudto sa mga utanon, diin anaa ang gugma, Kay sa linaming nga vaca ug ang pagdumot anaa niana.',
        18: 'Ang usa ka tawo nga masukanon nagahagit ug pagpakigaway; Apan kadtong mahinay sa pagkasuko nagapalinaw sa pagkabingkil.',
        19: 'Ang dalan sa tapulan maingon sa usa ka koral sa mga tunok; Apan ang dalan sa tawong matul-id gihimong usa ka halapad nga dalan',
        20: 'Ang usa ka anak nga manggialamon maoy kalipay sa iyang amahan; Apan ang usa ka tawong buangbuang nagatamay sa iyang inahan.',
        21: 'Ang binuang maoy kalipay niadtong walay kaalam; Apan ang tawo nga masinabuton nagatul-id sa iyang paglakaw.',
        22: 'Diin walay pagtambag, ang mga tinguha makawang; Apan diha sa panon sa mga magtatambag sila mangatukod.',
        23: 'Ang tawo may kalipay diha sa pagtubag sa iyang baba; Ug ang usa ka pulong nga angay sa panahon, pagkaayo niana!',
        24: 'Alang manggialamon ang dalan sa kinabuhi nagapadulong ngadto sa itaas, Aron siya mobiya gikan sa Sheol sa ubos.',
        25: 'Si Jehova magaluka sa balay sa mapahitas-on; Apan siya magapalig-on sa utlanan sa balo nga babaye.',
        26: 'Ang mga lalang nga dautan maoy dulumtanan kang Jehova; Apan ang mga pulong sa kalipay mga ulay man.',
        27: 'Kadtong hakog sa ganancia nagasamok sa iyang kaugalingong balay; Apan kadtong nagadumot sa mga hiphip mabuhi.',
        28: 'Ang kasingkasing sa tawong matarung nagatoon sa angay nga ipanubag; Apan ang baba sa dautan nagabubo sa mga dautang butang.',
        29: 'Si Jehova halayo sa mga dautan; Apan siya mamati sa pag-ampo sa mga tawong matarung.',
        30: 'Ang kahayag sa mga mata nagalipay sa kasingkasing; Ug ang mga maayong balita nagapatambok sa mga bukog.',
        31: 'Ang igdulongog nga mamati sa pagbadlong sa kinabuhi Magapuyo sa taliwala sa mga manggialamon.',
        32: 'Kadtong nagasalikway sa pagsaway nagatamay sa iyang kaugalingong kalag; Apan kadtong nagapamati sa pagbadlong nakakab-ut sa kahibalo.',
        33: 'Ang pagkahadlok kang Jehova maoy pagpahamatngon sa kaalam; Ug ang pagka-mapinaubsanon maga-una sa kadungganan.',
    },
    16: {
        1: 'Ang mga laraw sa kasingkasing iya sa tawo; Apan ang tubag sa dila gikan kang Jehova.',
        2: 'Ang tanang mga dalan sa tawo mahinlo sa iyang kaugalingong mga mata; Apan si Jehova nagatimbang sa mga espiritu.',
        3: 'Itugyan ang imong mga buhat ngadto kang Jehova, Ug ang imong mga tuyo mamalig-on.',
        4: 'Gihimo ni Jehova ang tanang butang alang sa iyang kaugalingong tuyo; Oo, bisan ang dautan alang sa adlaw nga dautan.',
        5: 'Ang tagsatagsa nga may pagkamapahitas-on sa kasingkasing maoy usa ka dulumtanan kang Jehova: Bisan pa ang kamot madugtong sa usa ka kamot, siya dili makagawas sa silot.',
        6: 'Tungod sa kalooy ug sa kamatuoran ang kasal-anan may pagtabon-sa-sala; Ug tungod sa pagkahadlok kang Jehova ang mga tawo mobiya gikan sa dautan.',
        7: 'Kong ang mga dalan sa usa ka tawo makapahimuot kang Jehova, Iyang pagahimoon bisan ang iyang mga kaaway nga makigdaiton uban kaniya.',
        8: 'Maayo pa ang diyutay uban ang pagkamatarung, Kay sa mga dagkung abut nga uban ang pagkadili-matarung.',
        9: 'Ang kasingkasing sa tawo magalalang sa iyang dalan; Apan si Jehova nagamando sa iyang mga lakang.',
        10: 'Ang diosnong pagpahamtang sa silot anaa sa mga ngabil sa hari; Ang iyang baba dili magalapas diha sa paghukom.',
        11: 'Ang matarung nga bato ug mga timbangan iya man ni Jehova; Ang tanang mga gibug-aton sa sako maoy iyang buhat.',
        12: 'Maoy usa ka dulumtanan alang sa mga hari ang pagpanugyan ngadto sa kadautan; Tungod kay ang trono natukod pinaagi sa pagkamatarung.',
        13: 'Ang matarung nga mga ngabil maoy kalipay sa mga hari; Ug sila nahagugma kaniya nga nagapamulong sa matarung.',
        14: 'Ang kaligutgut sa usa ka hari maingon sa mga sinugo sa kamatayon; Apan ang tawo nga manggialamon magapalinaw niini.',
        15: 'Diha sa kahayag sa nawong sa hari anaa ang kinabuhi; Ug ang iyang kalooy maingon sa usa ka panganod sa ulan nga kinaulahian.',
        16: 'Pagka-labing maayo ang pagbaton sa kaalam kay sa bulawan! Oo, ang pagbaton sa salabutan maayo pang pagapilion kay sa salapi.',
        17: 'Ang halapad-nga-dalan sa matarung mao ang pagbiya gikan sa dautan: Kadtong nagabantay sa iyang dalan nagaamping sa iyang kalag.',
        18: 'Ang pagkagarboso magauna sa pagkalaglag, Ug ang mapahitas-ong espiritu magauna sa pagkahulog.',
        19: 'Maayo pa nga magmapainubsanon sa espiritu uban sa mga kabus, Kay sa pagpakigbahin sa inagaw uban sa mga mapahitas-on.',
        20: 'Kadtong nagamatngon sa pulong makakaplag ug maayo; Ug bisan kinsa nga nagasalig kang Jehova, malipayon siya.',
        21: 'Ang manggialamon sa kasingkasing pagatawgon nga buotan; Ug ang pagkatam-is sa mga ngabil nagadugang sa kahibalo.',
        22: 'Ang salabutan maoy usa ka atabay nga tuburan sa kinabuhi niadtong nagabaton niini; Apan ang pagsaway sa mga buang mao ang ilong binuang.',
        23: 'Ang kasingkasing sa manggialamon nagapahamangno sa iyang baba, Ug nagadugang sa kinaadman sa iyang mga ngabil.',
        24: 'Ang makalilipay nga mga pulong ingon sa usa ka udlan sa dugos, Matam-is sa kalag ug makapalig-on sa mga bukog.',
        25: 'Adunay usa ka dalan nga daw matarung alang sa tawo, Apan ang katapusan niana mao ang mga dalan sa kamatayon.',
        26: 'Ang kahinam sa usa ka tawo nga mamumuo nagabuhat alang kaniya; Kay niini ang iyang baba nagaaghat kaniya.',
        27: 'Ang tawo nga walay kapuslanan nagalalang ug dautang buhat; Ug diha sa iyang mga ngabil adunay makasunog nga kalayo.',
        28: 'Ang tawo nga masukihon nagasabwag ug kabingkilan; Ug ang usa ka witwitan nagapabulag sa labing suod nga mga higala.',
        29: 'Ang tawo nga malupigon nagaulogulog sa iyang isigkatawo, Ug nagatultol kaniya diha sa dalan nga dili maayo.',
        30: 'Kadtong nagapiyong sa iyang mga mata, nagalalang sa mga butang nga sukwahi; Kadtong nagapanakmol sa iyang mga ngabil nagapahitabo sa dautan.',
        31: 'Ang ulo nga ubanon maoy purongpurong sa himaya; Kini igakita diha sa dalan sa pagkamatarung.',
        32: 'Kadtong mahinay sa kasuko labi pang maayo kay sa tawong gamhanan; Ug kadtong nagagahum sa iyang espiritu, kay niadtong nakaagaw sa usa ka ciudad.',
        33: 'Ang pagpapalad gihulog diha sa sabakan; Apan ang tibook pagpahinabo niana iya kang Jehova.',
    },
    17: {
        1: 'Maayo pa ang momho nga nauga, ug ang kalinaw uban niana, Kay sa usa ka balay nga napuno sa hudyaka nga inubanan sa pagkabingkil.',
        2: 'Ang usa ka ulipon nga nagapaagi sa pagkamanggialamon gayud magagahum sa usa ka anak nga nagapakaulaw, Ug makaambit sa bahin sa panulondon taliwala sa mga kaigsoonan.',
        3: 'Ang kolon tunawanan alang sa salapi, ug ang hasohasan alang sa bulawan; Apan si Jehova magasulay sa mga kasingkasing.',
        4: 'Ang mamumuhat sa kadautan magapamati sa dautang mga ngabil; Ug ang usa ka bakakon nagapatalinghug sa usa ka dila nga makadaut',
        5: 'Bisan kinsa nga nagayubit sa kabus nagatamay sa iyang Magbubuhat; Ug ang malipay sa panahon sa pagkaalaut dili makagawas sa silot.',
        6: 'Ang mga anak sa mga anak maoy purongpurong sa mga tawong tigulang; Ug ang himaya sa mga anak mao ang ilang mga amahan.',
        7: 'Ang pakigpulong nga labing maayo dili mahatungod sa usa ka buang; Labing dili angay ang bakakon nga mga ngabil sa usa ka principe.',
        8: 'Ang hiphip daw usa ka hamili nga bato diha sa mga mata kaniya nga magabaton niini; Sa bisan diin kini moliso kini magamauswagon.',
        9: 'Kadtong magatabon sa usa ka kalapasan nagapangita ug gugma; Apan kadtong magabutyag sa usa ka butang nagapabulag sa labing suod nga mga higala.',
        10: 'Ang usa ka pagbadlong motidlum sa halalum gayud nganha sa usa nga may salabutan Kay sa usa ka gatus nga mga labud nganha sa usa ka buang.',
        11: 'Ang tawong dautan magapangita lamang sa usa ka kagubot; Tungod niini ang usa ka mabangis nga sinugo igapadala batok kaniya.',
        12: 'Ipasugat sa usa ka oso nga nawad-an sa iyang mga anak ang usa ka tawo, Kay sa usa ka buang diha sa iyang binuang.',
        13: 'Bisan kinsa nga nagabalus ug dautan sa maayo, Ang dautan dili mopahawa gikan sa iyang balay.',
        14: 'Ang sinugdanan sa panagkabingkil maoy ingon sa usa nga magahuwad sa tubig: Busa biyai ang panaglalis sa dili pa ang panag-away.',
        15: 'Kadtong magapamatarung sa dautan, ug kadtong magasilot sa matarung, Silang duruha managsama maoy dulumtanan kang Jehova.',
        16: 'Busa aduna bay bili diha sa kamot sa usa ka buang aron sa pagpalit sa kaalam, Sanglit siya wala may salabutan?',
        17: 'Ang usa ka higala mahagugma sa tanang panahon; Ug ang usa ka igsoon matawo nga alang sa pagkaalaut.',
        18: 'Ang tawo nga walay salabutan magapanghampak sa kamot, Ug mahimong pasalig sa atubangan sa iyang isigkatawo.',
        19: 'Siya nga mahagugma sa pagkamalapason mahagugma sa pakigbingkil: Kadtong magaalsa sa itaas sa iyang ganghaan nagapangita sa kalumpagan.',
        20: 'Kadtong may masalaagon nga kasingkasing dili makakaplag sa maayo; Ug kadtong may usa ka masukihon nga dila mahulog sa kadautan.',
        21: 'Kadtong nanganak ug usa ka buang nakaangkon niini sa iyang kasub-anan; Ug ang amahan sa usa ka buang walay kalipay.',
        22: 'Ang kasingkasing nga malipayon maoy usa ka maayong tambal; Apan ang usa kamasulob-on nga espiritu nagapauga sa mga bukog.',
        23: 'Ang tawong dautan magadawat ug usa ka hiphip gikan sa sabakan, Aron sa pagbalit-ad sa mga dalan sa justicia.',
        24: 'Ang kaalam anaa sa atubangan sa nawong niadtong may salabutan; Apan ang mga mata sa usa ka buang anaa sa mga kinatumyan sa yuta.',
        25: 'Ang anak nga buangbuang maoy kasubo sa iyang amahan. Ug kapaitan niadtong nanganak kaniya.',
        26: 'Ang pagsilot usab sa matarung dili maayo, Ni ang pagbunal sa harianon alang sa ilang pagkatul-id.',
        27: 'Kadtong nagapugong sa iyang mga pulong may kahibalo; Ug kadtong may usa ka mabugnawng espiritu maoy usa ka tawo sa salabutan.',
        28: 'Bisan ang usa ka buang, kong siya magahilum, pagaisipon nga manggialamon; Kong siya magatak-om sa iyang mga ngabil, siya pagatamdon nga ingon sa buotan.',
    },
    18: {
        1: 'Kadtong nagalain sa iyang kaugalingon nagapangita sa iyang kaugalingong tinguha, Ug nakiglantugi batok sa tanang halalum nga kaalam.',
        2: 'Ang usa ka buang walay kalipay diha sa pagsabut, Apan mao lamang nga ang iyang kasingkasing magabutyag sa iyang kaugalingon.',
        3: 'Kong ang dautan moabut, modangat usab ang pagyubit, Ug uban sa pakaulaw, modangat ang pagtamay.',
        4: 'Ang mga pulong sa baba sa usa ka tawo maingon sa halalum nga mga tubig; Ang tubod sa atabay sa kaalam maingon sa usa ka sapa nga nagaagay.',
        5: 'Ang pagtamud sa pagkatawo sa usa ka tawong dautan dili maayo, Ni ang pagsalikway sa matarung diha sa paghukom.',
        6: 'Ang mga ngabil sa buang magadala kaniya ngadto sa pagkabingkil, Ug ang iyang baba magapanawag sa mga labud.',
        7: 'Ang baba sa usa ka buang maoy iyang kalaglagan, Ug ang iyang mga ngabil maoy lit-ag sa iyang kalag.',
        8: 'Ang mga pulong sa usa ka witwitan maingon sa usa ka malalim nga mga hungit nga kalan-on, Ug sila manganaug ngadto sa kinahiladmang mga dapit.',
        9: 'Siya usab nga tapulan sa iyang buhat Igsoon niadtong usa ka malaglagon.',
        10: 'Ang ngalan ni Jehova maoy usa ka malig-ong torre; Ang matarung magadalagan nganha niana ug may kaluwasan.',
        11: 'Ang bahandi sa usa ka adunahan nga tawo maoy iyang malig-on nga ciudad, Ug kini ingon sa usa ka hataas nga kuta sa iyang kaugalingong hunahuna.',
        12: 'Sa dili pa ang pagkalaglag mapahitas-on ang kasingkasing sa tawo; Ug sa dili pa ang kadungganan magauna ang pagkamapainubsanon.',
        13: 'Kadtong magahatag ug tubag sa wala pa niya madungog, Maoy usa ka binuang ug kaulawan alang kaniya.',
        14: 'Ang espiritu sa usa ka tawo maoy modasig sa iyang kaluya; Apan sa usa ka masulub-on nga espiritu kinsa ang makaantus?',
        15: 'Ang kasingkasing sa buotan magabaton sa kahibalo; Ug ang igdulungog sa manggialamon magapangita sa kahibalo.',
        16: 'Ang hatag sa usa ka tawo magahimo ug dapit alang kaniya, Ug magadala kaniya sa atubangan sa mga dagkung tawo.',
        17: 'Kadtong magalaban sa iyang katungod sa sinugdan daw matarung; Apan ang iyang isigkatawo moabut ug magasusi kaniya.',
        18: 'Ang pagpapalad magapahunong sa mga pagkabingkil, Ug magapabulag sa taliwala sa mga gamhanan.',
        19: 'Ang usa ka igsoon nga mahiubos labi pang magahi nga dag-on kay sa usa ka malig-on nga ciudad; Ug ang maong mga pagkabingkil sama sa mga trangka sa usa ka castillo.',
        20: 'Ang tiyan sa usa ka tawo pagabusgon sa bunga sa iyang baba; Uban sa abut sa iyang mga ngabil siya pagatagbawon.',
        21: 'Kamatayon ug kinabuhi maoy anaa sa gahum sa dila; Ug kadtong mahagugma niini magakaon sa bunga niana.',
        22: 'Bisan kinsa nga makakaplag ug usa ka asawa nakakaplag sa kaayohan. Ug makabaton sa kalooy ni Jehova.',
        23: 'Ang kabus magagamit sa mga pagpangaliyupo; Apan ang adunahan magatubag sa pagsingka.',
        24: 'Kadtong makahigala ug daghan magahimo niini alang sa iyang kaugalingong kadaut; Apan adunay usa ka higala nga mopabilin labaw pa kay sa usa ka igsoon.',
    },
    19: {
        1: 'Maayo pa ang kabus nga magalakat diha sa iyang pagkahingpit-sa-kasingkasing Kay kaniya nga sukwahi sa iyang mga ngabil ug maoy usa ka buang.',
        2: 'Ang kalag usab nga walay kahibalo dili maayo; Ug kadtong magadali sa iyang mga tiil magapakasala.',
        3: 'Ang binuang sa tawo nagapabaliko sa iyang dala; Ug ang iyang kasingkasing magalibak batok kang Jehova.',
        4: 'Ang bahandi magapadugang sa mga higala; Apan ang kabus ginapabulag gikan sa iyang mga higala.',
        5: 'Ang usa ka bakakon nga saksi dili pagagawason sa silot; Ug siya nga magapamulong sa mga bakak dili makalikay.',
        6: 'Daghang magapakilooy sa kalomo sa maabiabihong tawo; Ug ang tagsatagsa ka tawo maoy usa ka higala kaniya nga magahatag ug daghang mga gasa.',
        7: 'Ang tanang kaigsoonan sa kabus magadumot kaniya: Daw unsa pa ka labaw sa iyang mga higala nga magapahilayo gikan kaniya! Siya magaagpas kanila uban sa mga pulong, apan sila milakat na.',
        8: 'Kadtong magabaton ug kaalam mahagugma sa iyang kaugalingong kalag: Kadtong nagabantay sa salabutan makakaplag sa kaayohan.',
        9: 'Ang usa ka bakakon nga saksi dili makagawas sa silot; Ug kadtong mamulong sa kabakakan mahanaw.',
        10: 'Ang dinato nga pagkinabuhi dili angay sa usa ka buang; Labing dili angay nga ang usa ka ulipon magagahum sa mga principe.',
        11: 'Ang pagkabuotan sa usa ka tawo makapahimo kaniya nga mahinay sa pagkasuko; Ug maoy iyang himaya ang pagpasaylo sa kalapasan.',
        12: 'Ang kasuko sa hari maingon sa pagngulob sa usa ka leon; Apan ang iyang kalooy maingon sa yamog ibabaw sa balili.',
        13: 'Ang usa ka anak nga buang maoy kaalaut sa iyang amahan; Ug ang mga pakiglalis sa usa ka asawa maoy mga tinulo sa kanunay.',
        14: 'Balay ug mga bahandi maoy mga panulondon gikan sa mga amahan; Apan ang usa ka buotan nga asawa gikan kang Jehova.',
        15: 'Ang katapol makapahinanok sa halalum nga pagkatulog; Ug ang tapolan nga kalag magaantus sa kagutom.',
        16: 'Kadtong magabantay sa sugo nagabantay sa iyang kalag; Apan kadtong danghag sa iyang mga dalan, mamatay.',
        17: 'Kadtong may kalooy sa kabus magapahulam kang Jehova, Ug ang iyang maayong buhat pagabayran niya pag-usab.',
        18: 'Castigoha ang imong anak, sa natan-aw mo nga aduna pay paglaum; Ug ayaw pag-ibutang ang imong kasingkasing sa iyang kalaglagan.',
        19: 'Ang usa ka tawo nga anaa sa daku nga kasuko magapas-an sa silot; Kay kong ikaw magaluwas kaniya, kinahanglan nga ikaw magabuhat niana pag-usab.',
        20: 'Patalinghug sa tambag, ug dawata ang pahamatngon, Aron ikaw mahimong manggialamon sa imong kaulahian.',
        21: 'Adunay daghang mga lalang sulod sa kasingkasing sa usa ka tawo; Apan ang pagtambag ni Jehova, kana molungtad.',
        22: 'Kanang makapahimo sa usa ka tawo nga hiligugmaon mao ang iyang kalolot; Ug ang usa ka kabus nga tawo maayo pa kay sa usa ka bakakon.',
        23: 'Ang pagkahadlok kang Jehova nagapadulong ngadto sa kinabuhi; Ug kadtong makabaton niana magapuyo nga may pagkatagbaw; Siya dili pagadu-awon sa dautan.',
        24: 'Ang tapulan magalubong sa iyang kamot diha sa pinggan, Ug dili magadala niini pag-usab nganha sa iyang baba.',
        25: 'Bunali ang usa ka mayubiton, ug ang walay-pagtagad makakat-on ug pagkabuotan; Ug badlonga ang usa nga may salabutan, ug siya makasabut sa kahibalo.',
        26: 'Kadtong magapanlupig sa iyang amahan, ug magalutos sa iyang inahan, Maoy usa ka anak nga nagapakaulaw ug nagadala sa pagkatalamayon.',
        27: 'Hunong, anak ko sa pagpamati sa pahamatngon, Nga magatudlo lamang ngadto sa kasaypanan sa mga pulong sa kahibalo.',
        28: 'Ang usa ka walay-bili-nga-saksi nagabiaybiay sa katarungan; Ug ang baba sa dautan nagalamoy sa kasal-anan.',
        29: 'Ang mga paghukom giandam alang sa mga mayubiton, Ug ang mga labud alang sa bukobuko sa mga buang.',
    },
    20: {
        1: 'Ang vino maoy usa ka tigtamay, ang maisug nga ilimnon mao ang sabaan; Ug bisan kinsa nga masayup tungod niini dili manggialamon.',
        2: 'Ang pagkamakalilisang sa usa ka hari ingon sa pagngulob sa usa ka leon: Kadtong magahagit kaniya sa pagpakasuko magapakasala batok sa iyang kaugalingong kinabuhi.',
        3: 'Maoy usa ka kadungganan alang sa usa ka tawo ang pagpahilayo gikan sa pagpakig-away; Apan ang tagsatagsa ka buang magakaaway.',
        4: 'Ang tapulan dili modaro tungod sa panahon nga tingtugnaw; Busa siya magapakilimos sa tingani, ug walay maiya.',
        5: 'Ang tambag diha sa kasingkasing sa tawo ingon sa halalum nga tubig, Apan ang usa ka tawo nga may salabutan magatimba niini.',
        6: 'Ang kadaghanan sa mga tawo magabutyag sa tagsatagsa sa iyang kaugalingong kalolot; Apan sa usa ka matinumanon nga tawo kinsay makakaplag kaniya?',
        7: 'Ang usa ka tawong matarung magalakat diha sa iyang pagkahingpit sa kasingkasing, Bulahan ang iyang mga anak sunod kaniya.',
        8: 'Ang usa ka hari nga magalingkod sa trono sa paghukom Magapatibulaag sa tanang dautan pinaagi sa iyang mga mata.',
        9: 'Kinsay makaingon, gihimo ko ang akong kasingkasing nga malinis, Ako ulay gikan sa akong sala?',
        10: 'Ang nagkalainlaing mga timbangan ug nagkalainlaing mga sukdanan, Silang duruha managsama mga q2 dulumtanan kang Jehova.',
        11: 'Bisan ang usa ka bata magapaila sa iyang kaugalingon pinaagi sa iyang mga buhat, Kong ang iyang buhat maputi ba ug kong kini matarung ba.',
        12: 'Sa mapatalinghugon nga igdulungog, ug sa matinan-awong mata, Si Jehova ang nagbuhat bisan niining duruha.',
        13: 'Ayaw paghigugmaa ang pagkatulog, tingali unya ikaw modangat sa pagkakabus; Bukha ang imong mga mata, ug ikaw mabusog sa tinapay.',
        14: 'Dili maayo, dili maayo, nagapamulong ang pumapalit; Apan sa makalakaw na siya sa iyang dalan, unya siya magapangandak.',
        15: 'Adunay bulawan, ug daghang mga rubi; Apan ang mga ngabil sa kahibalo maoy usa ka bililhong mutya.',
        16: 'Kuhaa ang iyang panapton nga maoy pasalig alang sa usa ka lumalangyaw; Ug batonan mo siya sa usa ka saad nga maoy pasalig alang sa mga dumuloong.',
        17: 'Ang tinapay sa kabakakan matam-is sa usa ka tawo; Apan sa kaulahian ang iyang baba mapuno sa grava.',
        18: 'Ang tagsatagsa ka tuyo natukod pinaagi sa pagtambag; Ug pinaagi sa maalamong pagmando nakiggubat ikaw.',
        19: 'Kadtong magasuroysuroy ingon sa usa ka witwitan nagabutyag sa mga tinagoan; Busa ayaw pagpakigkauban niadtong magapalapad sa pagwalis sa iyang mga ngabil.',
        20: 'Bisan kinsa nga magatunglo sa iyang amahan kun sa iyang inahan, Ang iyang lamparahan pagapalongon diha sa kaitum sa kangitngitan.',
        21: 'Ang usa ka panulondon mahimong kuhaon sa hinanali sa sinugdanan; Apan ang katapusan niana dili pagabulahanon.',
        22: 'Dili ka mag-ingon: Ako mobalus sa dautan: Humulat ka kang Jehova, ug siya magaluwas kanimo.',
        23: 'Ang nagkalainlaing mga bato sa timbangan maoy usa ka dulumtanan kang Jehova; Ug ang usa ka limbongan nga timbangan dili maayo.',
        24: 'Ang mga pagpanlihok sa usa ka tawo iya ni Jehova; Nan unsaon man sa pagpakasabut sa tawo sa iyang dalan?',
        25: 'Kini maoy usa ka lit-ag sa usa ka tawo nga mamulong sa hinanali: Kini maoy balaan, Ug tapus sa mga panaad ang pagpakigsayud.',
        26: 'Ang usa ka hari nga manggialamon magaalig-ig sa dautan, Ug magapaligid kanila sa ligid sa giukan.',
        27: 'Ang espiritu sa tawo mao ang lamparahan ni Jehova, Nagasusi sa tanan niyang kinahiladman uyamut nga mga dapit.',
        28: 'Kalooy ug kamatuoran nagapanalipod sa hari; Ug ang iyang trono ginatuboy tungod sa kalolot.',
        29: 'Ang himaya sa mga batan-ong lalake mao ang ilang kusog; Ug ang katahum sa mga tigulang mao ang ilang ubanon nga ulo.',
        30: 'Ang mga labud nga makasamad makahugas sa dautan; Ug ang mga pagbunal molagbas sa kinahiladman uyamut nga mga dapit.',
    },
    21: {
        1: 'Ang kasingkasing sa hari anaa sa kamot ni Jehova maingon sa mga baha sa tubig: Siya nagapaliso niini sa bisan diin nga siya magabuot.',
        2: 'Ang tagsatagsa ka dalan sa usa ka tawo matarung sa iyang kaugalingong mga mata; Apan si Jehova magatimbang sa mga kasingkasing.',
        3: 'Ang pagbuhat sa pagkamatarung ug justicia Labi pang dawaton ni Jehova kay sa halad.',
        4: 'Ang usa ka tinan-awan nga mapahitas-on, ug ang usa ka palabilabihong kasingkasing, Bisan ang lamparahan sa dautan, sala man.',
        5: 'Ang mga hunahuna sa makugihon nagapadulong ngadto sa pagkadagaya; Apan ang tagsatagsa ka madalidalion nagadali lamang sa kawalad-on.',
        6: 'Ang pagbaton ug mga bahandi pinaagi sa usa ka bakakong dila Maoy usa ka gabon nga ginapalid ngadto ug nganhi niadtong nagapangita sa kamatayon.',
        7: 'Ang pagpanlupig sa dautan magasilhig kanila, Tungod kay sila nagadumili sa pagbuhat ug justicia.',
        8: 'Ang dalan niadtong natugob sa kasal-anan baliko gayud kaayo; Apan alang niadtong mga ulay, ang iyang buhat matarung.',
        9: 'Maayo pa ang pagpuyo diha sa pamag-angan sa atop sa balay, Kay sa pakigkauban sa usa ka makig-awayong babaye sa usa ka halapad nga balay.',
        10: 'Ang kalag sa dautan nagatinguha sa dautan: Ang iyang isigkatawo dili makakaplag ug kalooy diha sa iyang mga mata.',
        11: 'Kong ang mayubiton pagasilotan, ang walay-pagtagad mahimong manggialamon; Ug kong ang manggialamon pahamatngonon siya makadawat ug kahibalo.',
        12: 'Ang tawong matarung nagatulotimbang sa balay sa dautan, Unsaon sa pagkaunlod sa dautan ngadto sa ilang kapildihan.',
        13: 'Bisan kinsa nga magasampong sa iyang mga idgulungog sa pagtu-aw sa kabus, Siya usab magatu-aw ra, apan dili pagapatalinghugan.',
        14: 'Ang usa ka gasa sa tago magapapoypoy sa kasuko; Ug ang usa ka hatag diha sa sabakan, sa hilabihan nga kasuko.',
        15: 'Maoy kalipay sa matarung ang pagbuhat ug justicia; Apan maoy usa ka pagkalaglag sa mga mamumuhat sa kasal-anan.',
        16: 'Ang tawo nga nagasaagsaag gikan sa dalan sa pagsabut Magapahulay sa katilingban sa mga minatay.',
        17: 'Siya nga mahigugmaon sa kalingawan mahimong kabus nga tawo: Siya nga mahigugmaon sa vino ug lana dili maadunahan.',
        18: 'Ang dautan maoy usa ka lukat alang sa matarung; Ug ang maluibon modangat nga ilis sa matul-id',
        19: 'Maayo pang magpuyo sa usa ka yuta nga kamingawan, Kay sa pakig-ipon sa usa ka makig-awayon ug masuk-anon nga babaye.',
        20: 'Adunay bililhon nga bahandi ug lana diha sa puloy-anan sa manggialamon; Apan ang usa ka tawong buang magalamoy niana.',
        21: 'Kadtong magasunod sa pagkamatarung ug sa kalolot Makakaplag sa kinabuhi, pagkamatarung, ug kadungganan.',
        22: 'Ang usa ka manggialamon nga tawo makakatkat sa usa ka ciudad sa gamhanan, Ug makapukan sa kusog nga gisaligan niana.',
        23: 'Bisan kinsa nga magabantay sa iyang baba ug sa iyang dila, Magabantay sa iyang kalag gikan sa mga kasamok.',
        24: 'Ang tawong palabi-labihon ug garboso, mayubiton ang iyang ngalan; Siya magabuhat nga nagapakaaron-ingnon sa iyang pagkamapahitas-on.',
        25: 'Ang tinguha sa tapulan nagapatay kaniya; Kay ang iyang mga kamot nagadumili sa pagbuhat.',
        26: 'Adunay maibug sa pagkahakog gayud sa tibook adlaw; Apan ang matarung nagahatag ug wala magatungina.',
        27: 'Ang halad sa tawong dautan maoy usa ka dulumtanan; Daw unsa ka labaw pa gayud, kong iyang dad-on kini uban sa dautan nga hunahuna!',
        28: 'Ang usa ka bakakon nga saksi mahanaw; Apan ang tawo nga nagapamati nagapadayon sa iyang gipamulong.',
        29: 'Ang usa ka tawong dautan magapagahi sa iyang nawong; Apan mahitungod sa matul-id siya magalig-on sa iyang mga dalan.',
        30: 'Walay kaalam ni pagsabut Ni tambag batok kang Jehova.',
        31: 'Ang kabayo giandam batok sa adlaw sa gubat; Apan ang pagdaug iya kang Jehova.',
    },
    22: {
        1: 'Ang usa ka maayong ngalan labi pang maayong pilion kay sa dagkung mga bahandi, Ug ang mahigugmaong-kalooy kay sa salapi ug bulawan.',
        2: 'Ang adunahan ug ang kabus magakahibalag sila: Si Jehova mao ang nagbuhat kanilang tanan.',
        3: 'Ang usa ka buotan nga tawo makakita sa dautan, ug magatago sa iyang kaugalingon; Apan ang walay-pagtagad molabay lamang ug magaantus tungod niini.',
        4: 'Ang balus sa pagkamapaubsanon ug pagkahadlok kang Jehova Mao ang pagkaadunahan, ug kadungganan, ug kinabuhi.',
        5: 'Mga tonok ug mga lit-ag maoy anaa sa dalan sa masukihon: Kadtong magabantay sa iyang kalag mahilayo gikan kanila.',
        6: 'Bansaya ang bata diha sa dalan nga iyang pagalaktan, Ug bisan kong siya matigulang na siya dili mobiya gikan niana.',
        7: 'Ang adunahan magahari ibabaw sa kabus; Ug ang manghuhulam mao ang ulipon sa magapahulam.',
        8: 'Kadtong magapugas ug kasal-anan nagaani ug kalisdanan; Ug ang baras sa iyang kasuko makawang.',
        9: 'Kadtong adunay usa ka mata nga madagayaon pagabulahanon; Kay siya nagahatag sa iyang tinapay sa kabus.',
        10: 'Papahawaa ang mayubiton, ug ang pagpakigbingkil mogula; Oo, ang pagkalalis ug pagpakaulaw mohunong.',
        11: 'Kadtong mahagugma sa pagkaulay sa kasingkasing, Tungod sa gracia sa iyang mga q2 ngabilang hari mahimong iyan higala.',
        12: 'Ang mga mata ni Jehova magapanalipod kaniya nga may kahibalo; Apan siya magawagtang sa mga pulong sa tawong mabudhion',
        13: 'Ang tapulan nagaingon: Adunay usa ka leon sa gawas; Ako pagapatyon diha sa kadalanan.',
        14: 'Ang baba sa mga dumuloong babaye maoy usa ka halalum nga gahong; Siya nga gidumtan ni Jehova mahulog niana.',
        15: 'Ang mga binuang nabugkos diha sa kasingkasing sa usa ka bata; Apan ang bunal sa pagbadlong magapalabog niana sa halayo gikan kaniya.',
        16: 'Kadtong magadaugdaug sa kabus aron sa pagdugang sa iyang ganancia, Ug kadtong magahatag sa adunahan, modangat lamang sa kawalad-on.',
        17: 'Ikiling ang imong igdulungog, ug pamatia ang mga pulong sa manggialamon, Ug ibutang ang imong kasingkasing sa akong kahibalo.',
        18: 'Kay kini maoy butang nga makalilipay kong ikaw magatipig kanila diha kanimo, Kong sila mahiluna pagtingub diha sa imong mga ngabil.',
        19: 'Aron ang imong pagsalig mahaanha kang Jehova, Akong gipahibalo kanimo sila niining adlawa, bisan kanimo.',
        20: 'Wala ba ako makasulat kanimo ug mga maayo uyamut nga mga butang Sa mga tambag ug kahibalo,',
        21: 'Aron sa pagpahibalo kanimo sa kasayuran sa mga pulong sa kamatuoran, Aron ikaw magadala pagbalik sa mga pulong sa kamatuoran ngadto kanila nga nagasugo kanimo?',
        22: 'Ayaw pagkawati ang kabus tungod kay siya kabus; Ni magadaugdaug ka sa mga sinakit diha sa ganghaan:',
        23: 'Kay si Jehova magalaban sa ilang katungod, Ug moagaw sa kinabuhi niadtong nangagaw kanila.',
        24: 'Ayaw pagpakighigala sa usa ka tawo nga maligut-guton; Ug sa masuk-anon nga tawo dili ka makigkuyog:',
        25: 'Tingali unya ikaw makakat-on sa iyang mga dalan, Ug makabaton ka sa lit-ag sa imong kalag.',
        26: 'Dili ka paisip nga usa kanila nga nagapanghampak sa kamot, Kun kanila nga maoy mga pasalig tungod sa mga utang.',
        27: 'Kong ikaw walay kapaingnan sa pagbayad, Nganong iyang kuhaon ang imong higdaanan nga anaa sa ilalum nimo?',
        28: 'Ayaw pagbalhina ang karaan nga mohon sa yuta, Nga gibutang sa imong mga amahan.',
        29: 'Nakita mo ba ang usa ka tawo nga masingkamoton sa iyang patigayon? siya magatindog sa atubangan sa mga hari; Siya dili magatindog sa atubangan sa bastos nga mga tawo.',
    },
    23: {
        1: 'Kong ikaw magalingkod sa pagkaon uban sa usa ka punoan, Paniira sa masingkamoton siya nga anaa sa imong atubangan;',
        2: 'Ug ibutang ang usa ka cuchillo sa imong totonlan, Kong ikaw usa ka tawo nga ulipon sa kailibgon.',
        3: 'Ayaw pagtinguhaa ang iyang mga lamiang pagkaon; Sa nakita mo nga sila maoy malimbongon nga makaon.',
        4: 'Ayaw paghago sa imong kaugalingon sa pagpakadato; Hunong gikan sa imong kaugalingong kaalam.',
        5: 'Ibutang mo ba ang imong mga mata ibabaw nianang dili mao? Kay sa pagkatinuod ang mga bahandi magahimo ug mga pako sa ilang kaugalingon, Sama sa usa ka agila nga nagalupad paingon ngadto sa langit.',
        6: 'Ayaw pagkan-a ang tinapay niya nga may usa ka dautan nga mata, Ni kaibgan mo ang iyang mga lamiang makaon:',
        7: 'Kay maingon nga siya nagahunahuna sa sulod sa iyang kaugalingon, sa ingon niana mao man siya: Kumaon ka ug uminum, siya magaingon kanimo; Apan ang iyang kasingkasing wala iduyog kanimo.',
        8: 'Ang usa ka hungit nga imong nakaon imong igasuka, Ug pagulaa ang imong mga q2 matam-is nga pulong.',
        9: 'Ayaw pagsulti diha sa pagdungog sa usa ka buang; Kay siya magatamay sa kaalam sa imong mga pulong.',
        10: 'Ayaw pagbalhina ang karaang mohon sa yuta; Ug ayaw pagsulod sa kaumahan sa mga ilo:',
        11: 'Kay ang ilang Mamamawi kusganon man; Siya magalaban sa ilang katungod batok kanimo.',
        12: 'Ibutang ang imong kasingkasing sa pahamatngon, Ug ang imong mga igdulungog sa mga pulong sa kahibalo.',
        13: 'Ayaw pagpunggi ang pagbadlong gikan sa bata; Kay kong imong hampakon siya sa bunal, siya dili mamatay.',
        14: 'Imong pagahampakon gayud siya uban sa bunal, Ug maluwas ang iyang kalag gikan sa Sheol.',
        15: 'Anak ko, kong ang imong kasingkasing magmaalamon, Ang akong kasingkasing magamalipayon, bisan ang akong kasingkasing:',
        16: 'Oo, ang akong kasingkasing magamalipayon, Kong ang imong mga ngabil magapamulong sa mga butang nga matarung.',
        17: 'Ayaw itugot sa imong kasingkasing sa pagkasina sa mga makasasala; Apan himoa ang pagkahadlok kang Jehova sa tanang mga adlaw:',
        18: 'Kay sa pagkatinuod adunay usa ka balus; Ug ang imong paglaum dili pagaputlon.',
        19: 'Mamati ka, anak ko, ug magmaalamon ka, Ug mandoi ang imong kasingkasing diha sa dalan.',
        20: 'Ayaw pagtipon taliwala sa mga palainum sa vino, Taliwala sa mga ulitan nga komakaon sa unod:',
        21: 'Kay ang palahubog ug ang ulitan modangat sa kawalad-on; Ug ang pagkahingatulog magapasaput sa usa ka tawo sa mga nuog.',
        22: 'Pamati sa imong amahan nga nanganak kanimo, Ug ayaw pagtamaya ang imong inahan kong siya matigulang na.',
        23: 'Palita ang kamatuoran, ug ayaw kini pag-ibaligya; Oo, ang kaalam, ug pahamatngon, ug ang salabutan.',
        24: 'Ang amahan sa matarung malipayon sa daku uyamut; Ug kadtong manganak sa usa ka manggialamon nga bata nagamalipayon tungod kaniya.',
        25: 'Lipaya ang imong amahan ug ang imong inahan, Ug pasadyaa siya nga nanganak kanimo.',
        26: 'Anak ko, ihatag kanako ang imong kasingkasing; Ug ipahimuot sa imong mga mata ang akong mga dalan.',
        27: 'Kay ang usa ka bigaon maoy usa ka halalum nga kanal; Ug ang usa ka babaye nga dumuloong maoy usa ka masigpit nga gahong.',
        28: 'Oo, siya magabanhig ingon sa usa ka kawatan, Ug magadugang sa mga maluibon sa taliwala sa mga tawo.',
        29: 'Kinsa man ang may kasakit? kinsa man ang may kasubo? kinsa man ang may panagkabingkil? Kinsa man ang may pagbagulbol? kinsa man ang may mga samad sa walay gipasikaran? Kinsa man ang may kapula sa mga mata?',
        30: 'Mao kadtong magapabilin sa pag-inum-inum ug vino; Kadtong magapanggula aron sa pagpangita sa sinakot nga vino.',
        31: 'Dili ka magtan-aw sa vino kong kini magapula, Kong kini magapangidlap sulod sa copa, Sa diha nga kini magaagay nga mahapsay:',
        32: 'Kay sa katapusan kini magapamaak sama sa bitin, Ug moikos sama sa udto-udto.',
        33: 'Ang imong mga mata makasudong sa mga butang nga katingalahan, Ug ang imong kasingkasing magapamulong sa baliko nga mga butang.',
        34: 'Oo, ikaw maingon niadtong nagahigda sa kinataliwad-an sa dagat, Kun maingon niadtong nagahigda sa kinatumyan sa palo sa sakayan.',
        35: 'Sila nagbunal kanako, moingon ka, ug ako wala maunsa; Sila naglatos kanako, ug kini wala ko batia: Anus-a ba ako magamata? Pangitaon ko pa kini pag-usab.',
    },
    24: {
        1: 'Dili ka masina sa mga dautang tawo; Ni magtinguha ka sa pagpakiguban kanila:',
        2: 'Kay ang ilang kasingkasing magatoon sa pagdaugdaug, Ug ang ilang mga ngabil magapamulong sa dautang buhat.',
        3: 'Pinaagi sa kaalam natukod ang usa ka balay; Ug pinaagi sa salabutan kini nalig-on;',
        4: 'Ug pinaagi sa kahibalo nangapuno ang mga lawak Sa tanang mga bililhon ug makalilipay nga mga bahandi.',
        5: 'Ang usa ka tawo nga manggialamon kusganon man; Oo, ang usa ka tawo sa kahibalo magauswag sa kagahum.',
        6: 'Kay pinaagi sa maalamon nga pagmando ikaw magahimo sa imong gubat; Ug diha sa panon sa mga magtatambag walay kapildihan.',
        7: 'Ang kaalam hataas ra kaayo alang sa usa ka buang: Siya dili makabuka sa iyang baba diha sa ganghaan.',
        8: 'Siya nga magalalang sa pagbuhat ug dautan, Ang mga tawo magatawag kaniya nga usa ka mamumuhat sa kadautan.',
        9: 'Ang hunahuna nga binuang sala man; Ug ang mayubiton maoy usa ka dulumtanan sa mga tawo.',
        10: 'Kong ikaw punawan sa adlaw sa kalisdanan, Ang imong kusog diyutay ra.',
        11: 'Luwason mo kadtong nangadala ngadto sa kamatayon, Ug kadtong mga naandam naaron pagapatyon tan-awa nga sila imong magunitan.',
        12: 'Kong ikaw moingon: Ania karon, wala kami manghibalo niini; Wala ba siya nga nagatimbang sa mga kasingkasing magahunahuna niini? Ug siya nga nagabantay sa imong kalag, wala ba siya mahibalo niini? Ug wala ba siya magabalus sa tagsatagsa ka tawo sumala sa iyang buhat?',
        13: 'Anak ko, kumaon ka ug dugos, kay kini maayo; Ug ang mga tinulo sa udlan, nga mga matam-is sa imong pagtilaw:',
        14: 'Sa ingon niini ikaw mahibalo ug kaalam nga modangat sa imong kalag; Kong ikaw makakaplag niini, nan adunay usa ka balus, Ug ang imong paglaum dili makawang.',
        15: 'Ayaw pagbanhig, Oh dautan nga tawo, batok sa puloy-anan sa matarung; Ayaw paggun-oba ang iyang dapit nga pahulayan:',
        16: 'Kay ang usa ka matarung nga tawo mapukan sa makapito, ug mobangon pag-usab; Apan ang dautan ginalaglag pinaagi sa pagkaalaut.',
        17: 'Ayaw pag-ikalipay kong ang imong kaaway mapukan, Ug ayaw papagmayaa ang imong kasingkasing kong siya mapukan,',
        18: 'Tingali unya si Jehova makakita niini, ug kini dili makapahimuot kaniya, Ug ipaiway niya ang iyang kasuko gikan kaniya.',
        19: 'Ayaw ikasubo sa imong kaugalingon tungod sa mga mamumuhat sa kadautan; Ni masina ka sa dautan:',
        20: 'Kay walay igabalus sa dautan nga tawo; Ang lamparahan sa dautan pagapalongon.',
        21: 'Anak ko, kahadlokan mo si Jehova ug ang hari; Ug ayaw pagkuyog kanila nga mabalhin-balhinon:',
        22: 'Kay ang ilang kagul-anan modangat sa hinanali; Ug ang pagkalaglag gikan kanilang duruha, kinsay mahibalo niini?',
        23: 'Kini usab maoy mga sanglitanan sa manggialamon. Ang may pagkapinalabi sa mga tawo diha sa paghukom dili maayo.',
        24: 'Siya nga magaingon sa dautan: Ikaw matarung, Ang mga katawohan magatunglo kaniya, ang mga nasud pagalud-on kaniya;',
        25: 'Apan kanila nga magabadlong kaniya magakalipay, Ug ang usa ka maayong panalangin moabut kanila.',
        26: 'Siya magahalok sa mga ngabil Niadtong nagahatag ug usa ka q2 matarung nga tubag.',
        27: 'Hikaya ang imong buhat sa gawas, Ug andama kini alang kanimo diha sa uma; Ug sa human niini tukora ang imong balay.',
        28: 'Dili ka magsaksi batok sa imong isigkatawo sa walay gipasikaran; Ug dili ka maglimbong uban sa imong mga ngabil.',
        29: 'Ayaw pag-ingon: Buhaton ko kaniya ingon sa iyang gibuhat kanako; Ako magahatag sa tawo sumala sa iyang buhat.',
        30: 'Ako miagi duol sa uma sa tapulan, Ug sa kaparrasan sa tawo nga walay salabutan;',
        31: 'Ug, ania karon, kini gipanugkan sa ibabaw ug mga tunok, Ang nawong niana naputos sa mga nipay, Ug ang bato nga kuta niana nalumpag na.',
        32: 'Unya nasud-ong ko, ug naghunahuna pag-ayo; Nakita ko, ug nadawat ko ang pahamatngon:',
        33: 'Bisan pa niini diyutay nga katulog, usa ka diyutay nga hinanok, Usa ka diyutay nga pagkiyugpos sa mga kamot aron sa pagkatulog:',
        34: 'Busa ang imong pagkakabus moabut ingon sa usa ka tulisan, Ug ang imong kawalad-on ingon sa usa ka tawo nga sangkap sa hinagiban.',
    },
    25: {
        1: 'Kini usab mao ang mga proverbio ni Salomon, nga gihulad sa mga tawo ni Ezechias nga hari sa Juda.',
        2: 'Maoy himaya sa Dios ang pagtago sa usa ka butang; Apan ang himaya sa mga hari mao ang pagpangita sa usa ka butang.',
        3: 'Ingon nga ang kalangitan alang sa kahitas-an, ug ang yuta alang sa kahiladman, Maingon man ang kasingkasing sa mga hari dili matukib.',
        4: 'Kuhaa ang taya gikan sa salapi, Ug didto magagula ang usa ka sudlanan alang sa mag-uulay:',
        5: 'Kuhaa ang dautan gikan sa atubangan sa hari, Ug ang iyang trono mamatukod diha sa pagkamatarung.',
        6: 'Ayaw pahimayaa ang imong kaugalingon diha sa presencia sa hari, Ug ayaw pagbarug ilis sa dapit sa mga dagkung tawo:',
        7: 'Kay labing maayo nga igaingon kanimo: Sumaka ka ngari, Kay sa pagbutang kanimo sa labing ubos diha sa presencia sa principe, Nga makita sa imong mga mata.',
        8: 'Dili ka magmadali-dalion sa pagpanlimbasog, Tingali unya dili ka mahibalo sa imong pagabuhaton sa katapusan niana, Sa diha nga ang imong isigkatawo magapakaulaw kanimo.',
        9: 'Pakiglantugi sa imong katungod uban sa imong isigkatawo lamang, Ug ayaw pag-ibutyag ang tinago sa ubang tawo;',
        10: 'Tingali unya siya nga nagadungog niini magabuyboy kanimo, Ug ang imong kaulaw dili mobulag gikan kanimo.',
        11: 'Ang usa ka pulong nga maayong pagkagamit Sama sa mga mansanas nga bulawan diha sa linala nga salapi.',
        12: 'Maingon sa usa ka ariyos nga bulawan, ug sa usa ka dayandayan sa fino nga bulawan, Ingon man ang usa ka manggialamon nga magbabadlong ibabaw sa usa ka masinugtanon nga igdulungog.',
        13: 'Ingon sa kabugnawon sa nieve sa panahon sa ting-ani, Busa mao man ang usa ka q2 matinumanon nga sulogoon kanila nga nagasugo kaniya; Kay siya nagalipay sa kalag sa iyang mga agalon.',
        14: 'Ingon sa mga panganod ug sa hangin nga walay ulan, Maingon man siya nga nagapagarbo sa iyang kaugalingon sa iyang mga gasa nga dili matuod.',
        15: 'Tungod sa hataas nga pagpailub nalukmay ang usa ka magbubuot, Ug ang usa ka malomo nga dila nakapadugmok sa bukog.',
        16: 'Nakakaplag ba ikaw ug dugos? kumaon ka sumala sa igo kanimo, Tingali unya ikaw mabusog ug magasuka niana.',
        17: 'Ayaw pagpakanunaya ang imong tiil sa balay sa imong isigkatawo, Tingali unya siya pul-an kanimo, ug magdumot kanimo.',
        18: 'Ang usa ka tawo nga nagasaksi ug bakak batok sa iyang isigkatawo Maoy usa ka mazo, ug usa ka pinuti, ug usa ka maidlut nga udyong.',
        19: 'Ang pagsalig diha sa usa ka maluibon nga tawo sa panahon sa kasamok Mahasama sa usa ka naputol nga ngipon, ug sa usa ka tiil nga nalisa.',
        20: 'Ingon sa usa nga nagahukas ug saput sa tingtugnaw, ug ingon sa suka ibabaw sa soda, Mao man siya nga nagaawit sa mga awit sa usa ka masulob-on nga kasingkasing.',
        21: 'Kong ang imong kaaway pagagutomon, hatagi siya ug tinapay nga makaon; Ug kong siya pagauhawon, hatagi siya ug tubig nga imnon:',
        22: 'Kay ikaw magatapok ug mga baga sa kalayo ibabaw sa iyang ulo, Ug si Jehova magabalus kanimo.',
        23: 'Ang hangin sa amihan nagadala ug ulan; Busa mao man ang usa ka malibakon nga dila sa usa ka masuk-anon nga panagway.',
        24: 'Maayo pang magpuyo diha sa pamag-ang suok sa atop sa balay, Kay sa pagpakigkauban sa usa ka babaye nga palaaway diha sa hamugaway nga balay.',
        25: 'Ingon sa bugnaw nga katubigan alang sa usa ka giuhaw nga kalag, Mao man ang maayong balita nga gikan sa halayong yuta.',
        26: 'Ingon sa usa ka nalubog nga tinubdan, ug sa nahugawan nga tuburan, Mao man ang usa ka matarung tawo nga madaug sa atubangan sa dautan.',
        27: 'Dili maayo ang pagkaon sa hilabihang kadaghan sa dugos; Busa alang sa mga tawo nga magapangita sa ilang kaugalingong himaya mabug-at sa hilabihan.',
        28: 'Siya kang kinsang espiritu walay pagpugong Sama sa usa ka ciudad nga nalumpag ug walay mga kuta.',
    },
    26: {
        1: 'Maingon sa nieve sa ting-init, ug maingon sa ulan sa ting-ani, Mao man ang kadungganan dili angay sa usa ka buang.',
        2: 'Maingon sa gorion sa iyang pagpanaw, maingon sa ayaw sa iyang paglupad, Mao man ang pagpanghimaraut nga walay gipasikaran dili matuman.',
        3: 'Usa ka pudlos alang sa kabayo, usa ka busal alang sa asno, Ug ang usa ka bunal alang sa likod sa mga buang.',
        4: 'Ayaw gayud pagtubaga ang usa ka buang sumala sa iyang binuang, Tingali unya ikaw mahasama usab kaniya.',
        5: 'Tubaga ang usa ka buang sumala sa iyang binuang, Tingali unya siya mahimong manggialamon sa iyang kaugalingong paghunahuna.',
        6: 'Kadtong nagapadala ug usa ka panugon pinaagi sa kamot sa usa ka buang, Nagaputol sa iyang kaugalingong mga tiil, ug nagainum diha sa kapildihon.',
        7: 'Ang mga paa sa piang magabitay nga nanagtabyog; Ingon niana ang usa ka sambingay sa baba sa mga buang.',
        8: 'Maingon sa usa ka tawo nga nagatakgos sa usa ka bato diha sa usa ka saplong, Ingon man usab siya nga nagahatag ug kadungganan sa usa ka buang.',
        9: 'Ingon sa usa ka tunok nga nagalagbas sa kamot sa usa ka palahubog, Mao usab niana ang usa ka sambingay diha sa baba sa mga buang.',
        10: 'Maingon sa usa ka magpapana nga nagasamad sa tanan, Mao man usab siya nga nagasuhol sa usa ka buang ug siya nga nagasuhol kanila nga nagapanlabay.',
        11: 'Maingon sa usa ka iro nga nagabalik sa iyang sinuka, Ingon niana ang usa ka buang nga nagabalikbalik sa iyang binuang.',
        12: 'Nakita mo ba ang usa ka tawo nga manggialamon sa iyang kaugalingong paghunahuna? Aduna pay labaw nga paglaum sa usa ka buang kay kaniya.',
        13: 'Ang tapulan nagaingon: Adunay usa ka leon sa dalan; Usa ka leon anaa sa kadalanan.',
        14: 'Maingon nga ang pultahan motakoptak-op diha sa iyang mga bisagra, Ingon niana ang tapulan ibabaw sa iyang higdaanan.',
        15: 'Ang tapulan nagalubong sa iyang kamot diha sa pinggan; Nakapakapoy na kaniya ang pagdala pag-usab niini ngadto sa iyang baba.',
        16: 'Ang tapulan manggialamon pa sa iyang kaugalingon paghunahuna Kay sa pito ka tawo nga nakahatag ug usa ka katarungan.',
        17: 'Kadtong molabay, ug magabudlay sa iyang kaugalingon sa pagpakig-away nga dili iya, Sama sa usa ka tawo nga nagadakup sa usa ka iro pinaagi sa mga dalunggan.',
        18: 'Maingon sa usa ka nabuang tawo nga nagasalibay sa mga agipo, Mga udyong, ug kamatayon,',
        19: 'Mao man ang tawo nga nagalimbong sa iyang isigkatawo, Ug nagaingon: Wala ba ako magti-aw lamang?',
        20: 'Tungod sa kakulang sa kahoy nga isugnod ang kalayo mapalong; Ug diin walay witwitan, ang pagpakig-away mohunong.',
        21: 'Maingon nga ang mga uling alang sa mainit nga mga abo, ug ang kahoy nga isugnod alang sa kalayo, Ingon niana ang usa ka makigawayon nga tawo aron sa pagpasilaub sa away.',
        22: 'Ang mga pulong sa usa ka witwitan maingon sa lamian nga mga hungit, Ug sila mosulod ngadto sa halalum uyamut nga mga bahin.',
        23: 'Ang mainit nga mga ngabil ug ang usa ka dunot nga kasingkasing Sama sa usa ka sudlanan nga yuta nga hinal-upan sa taya sa salapi.',
        24: 'Siya nga nagadumot ngalimbong tungod sa iyang mga ngabil; Apan nagahan-ay siya ug limbong sa sulod niya:',
        25: 'Sa diha nga siya magasulti ug maayo-ayo, ayaw siya pagtohoi; Kay adunay pito ka mga dulumtanan diha sa iyang kasingkasing:',
        26: 'Bisan pa nga ang iyang pagdumot nagatabon ug limbong sa iyang kaugalingon, Ang iyang pagkadautan madayag sa atubangan sa katilingban.',
        27: 'Bisan kinsa nga nagakalot ug usa ka gahong mahulog niana; Ug kadtong nagaligid ug usa ka bato, kini igabalik sa ibabaw niya.',
        28: 'Ang usa ka bakakon nga dila nagadumot niadtong iyang gipanamaran; Ug ang usa ka maulog-ulogon nga baba nagabuhat sa kalaglagan.',
    },
    27: {
        1: 'Ayaw pagpagarbo sa imong kaugalingon mahitungod sa kaugmaon; Kay ikaw wala mahibalo kong unsay madala sa usa ka adlaw.',
        2: 'Padayega ang laing tawo mahitungod kanimo, ug dili ang imong kaugalingon nga baba; Ang usa ka dumuloong, ug dili ang imong kaugalingong mga ngabil.',
        3: 'Ang usa ka bato mabug-at, ug ang balas maugdang; Apan ang kagul-anan sa usa ka buang labing mabug-at pa kay sa duruha.',
        4: 'Ang kasuko dagmalan, ug ang kaligutgut makapalumos; Apan kinsa ba ang makaasdang sa atubangan sa pangabugho?',
        5: 'Maayo pa ang pagbadlong sa dayag Kay sa gugma nga tinago.',
        6: 'Matinumanon ang mga samad sa usa ka higala; Apan ang mga halok sa usa ka kaaway malimbongon.',
        7: 'Ang busog nga kalag ginaluod sa udlan; Apan alang sa gigutom nga kalag ang tagsatagsa ka mapait nga butang maoy matam-is.',
        8: 'Maingon sa usa ka langgam nga nagasaagsaag gikan sa iyang salag, Ingon niana ang usa ka tawo nga nagalibud-suroy gikan sa iyang dapit.',
        9: 'Ang lana ug ang pahumot nagalipay sa kasingkasing; Ingon niana ang katam-is sa higala sa usa ka tawo nga nahiabut uban ang kinasingkasing nga pagtambag.',
        10: 'Ang imong kaugalingon nga higala, ug ang higala sa imong amahan, ayaw pagtalikdi; Ug ayaw pag-adto sa balay sa imong igsoon sa adlaw sa imong kalisdanan: Maayo pa ang usa ka isigkatawo nga haduol kay sa usa ka igsoon nga atua sa halayo.',
        11: 'Anak ko, magmaalamon ka, ug lipaya ang akong kasingkasing, Aron matubag ko siya nga nagatamay kanako.',
        12: 'Ang usa ka buotan nga tawo makakita sa dautan, ug magatago sa iyang kaugalingon; Apan ang walay-pagtagad nagapadayon, ug nagaantus tungod niini.',
        13: 'Kuhaa ang iyang panapton nga maoy pasalig sa usa ka dumuloong; Ug ibutang siya sa saad nga maoy pasalig alang sa usa ka lumalangyaw nga babaye.',
        14: 'Siya nga manalangin sa usa ka higala uban sa usa ka makusog nga tingog, sa pagbangon sayo sa kabuntagon, Kini pagaisipon nga usa ka panghimaraut alang kaniya.',
        15: 'Ang kanunay nga pagtulo sa adlaw sa ting-ulan Ug ang usa ka makig-awayon nga babaye managsama:',
        16: 'Siya nga magapugong kaniya nagapugong sa hangin; Ug sa iyang toong kamot gikahibalag ang lana.',
        17: 'Ang puthaw magapahait sa puthaw; Ingon niana ang usa ka tawo magapahait sa panagway sa iyang higala.',
        18: 'Bisan kinsa nga magabantay sa higuera magakaon sa bunga niana; Ug kadtong magatahud sa iyang agalon pagapasidunggan.',
        19: 'Ingon nga ang tubign magapakita sa nawong ug nawong, Busa ang kasingkasing sa tawo ngadto sa tawo.',
        20: 'Ang Sheol ug ang Abaddon dili gayud matagbaw; Ug ang mga mata sa tawo dili gayud matagbaw.',
        21: 'Ang tunawan nga kolon alang sa salapi, ug ang hasohasan alang sa bulawan; Ug ang usa ka tawo pagaulayon tungod sa iyang pagdayeg.',
        22: 'Bisan pa ikaw magadugmok sa usa ka buang sa usa ka lusong pinaagi sa usa ka alho lakip sa linubok nga trigo, Apan ang iyang binuang dili gayud mobiya gikan kaniya.',
        23: 'Magmasingkamoton ka sa pagkahibalo sa kahimtang sa imong mga panon sa carnero, Ug tan-awa pag-ayo ang imong kahayupan:',
        24: 'Kay ang mga bahandi dili magapadayon; Ug ang purongpurong molungtad ba sa tibook mga kaliwatan?',
        25: 'Ang kumpay ginadala, ug ang udlot sa mga balili nanagpanggitib, Ug ang mga utanon sa kabukiran ginahipos.',
        26: 'Ang mga nating carnero alang sa imong saput, Ug ang mga kanding mao ang bili sa uma;',
        27: 'Ug adunay gatas sa kanding nga igo alang sa imong pagkaon, alang sa pagkaon sa imong panimalay, Ug kabuhian nga alang sa imong kadalagahan.',
    },
    28: {
        1: 'Ang tawong dautan mokalagiw bisan walay tawo nga magalutos; Apan ang matarung maisug ingon sa leon.',
        2: 'Kay sa kalapasan sa usa ka yuta daghanan ang mga principe niana; Apan pinaagi sa mga tawo nga may salabutan ug kahibalo ang kahimtang niini pagalugwayan.',
        3: 'Ang usa ka tawo sa kawalad-on nga magalupig sa mga kabus Mahasama sa ulan nga nagabanlas nga dili magabilin ug makaon.',
        4: 'Kadtong mobiya sa Kasugoan nagadayeg sa tawong dautan; Apan ang mga magabantay sa Kasugoan nakig-bisog batok kanila.',
        5: 'Ang dautang mga tawo dili makasabut sa justicia; Apan sila nga nangita kang Jehova makasabut sa tanang mga butang.',
        6: 'Maayo pa ang kabus nga nagalakat sa iyang pagkahingpit sa kasingkasing, Kay kaniya nga sukwahi sa iyang mga dalan, bisan siya dato.',
        7: 'Bisan kinsa nga nagabantay sa Kasugoan maoy usa ka anak nga manggialamon; Apan kadtong kauban sa mga ulitan nagapakaulaw sa iyang amahan.',
        8: 'Kadtong nagapadaghan sa iyang manggad pinaagi sa tubo ug abut, Nagahipos niini alang kaniya nga may kalooy sa kabus.',
        9: 'Kadtong nagapalingog-iingog sa iyang igdulungog gikan sa pagpamati sa Kasugoan, Bisan ang iyang pag-ampo maoy usa ka dulumtanan.',
        10: 'Bisan kinsa nga nagapasalaag sa matul-id ngadto sa usa ka dautan nga dalan, Siya mahulog sa kaugalingon niyang gahong; Apan ang hingpit magapanunod sa maayo.',
        11: 'Ang adunahan nga tawo manggialamon sa iyang kaugalingong hunahuna; Apan ang kabus nga may salabutan magasusi kaniya.',
        12: 'Sa diha nga ang matarung makadaug adunay dakung himaya; Apan sa diha nga ang dautan motindog, ang mga tawo manago sa ilang kaugalingon.',
        13: 'Kadtong nagatabon sa iyang kalapasan dili mouswag; Apan bisan kinsa nga nagasugid ug nagabiya kanila makadawat ug kalooy.',
        14: 'Malipayon ang tawo nga mahadlokon sa kanunay; Apan kadtong nagapagahi sa iyang kasingkasing mahulog ngadto sa dautang buhat.',
        15: 'Maingon sa usa ka leon nga nagangulob, ug sa usa ka oso nga nagasarasay, Ingon niana ang usa ka dautan nga punoan ibabaw sa usa ka kabus nga katawohan.',
        16: 'Ang principe nga kulang sa salabutan maoy daku usab nga madaugdaugon; Apan siya nga nagadumot sa pagkaibug magapalugway sa iyang mga adlaw.',
        17: 'Ang tawo nga mahimug-atan sa dugo sa bisan kinsang tawo Mokalagiw ngadto sa gahong; ayaw pagpapunggi sa tawo siya.',
        18: 'Bisan kinsa nga nagalakat sa katarung pagagawason; Apan kadtong sukwahi sa iyang mga dalan mahulog sa walay langan.',
        19: 'Kadtong nagabaul sa iyang yuta makabaton ug daghang mga makaon; Apan siya nga nagasunod sa mga tawo sa kakawangan makabaton sa hilabihan uyamut nga kakabus.',
        20: 'Ang usa ka matinumanon nga tawo magamadagayaon sa mga panalangin; Apan kadtong nagadali sa pagkaadunahan dili makalikay sa silot.',
        21: 'Ang may pagkapinalabi sa mga tawo dili maayo; Ni ang usa ka tawo magmalinapason tungod lamang sa usa ka tipik nga tinapay.',
        22: 'Kadtong may usa ka dautan nga mata nagadali sa pagkab-ut sa mga bahandi, Ug wala mahibalo nga ang kawalad-on modangat kaniya.',
        23: 'Kadtong nagabadlong sa usa ka tawo makakaplag ug labawng kalooy sa dili madugay Kay kaniya nga nagaulo-ulo uban sa dila.',
        24: 'Bisan kinsa nga mangawat sa iyang amahan kun sa iyang inahan, ug moingon: Dili kini Kalapasan, Apan maong tawo maoy kauban sa usa ka maglalaglag.',
        25: 'Kadtong may hakog nga espiritu nagaagda sa panag-away; Apan kadtong nagabutang sa iyang pagsalig kang Jehova mahimong matambok.',
        26: 'Kadtong nagasalig sa iyang kaugalingong kasingkasing maoy usa ka buang; Apan bisan kinsa nga nagalakat sa pagkamanggialamon pagaluwason.',
        27: 'Kadtong nagahatag sa kabus dili makulangan; Apan kadtong nagatago sa iyang mga mata makabaton ug daghang mga panghimaraut.',
        28: 'Kong ang dautan motindog, ang mga tawo manago sa ilang kaugalingon; Apan sa diha nga sila mangahanaw, ang mga matarung modaghan.',
    },
    29: {
        1: 'Kadtong sa masubsob ginabadlong nagapatikig sa iyang liog Sa hinanali pagalaglagon, ug kana wala nay kaayohan.',
        2: 'Kong ang matarung maoy modaghan, ang katawohan malipayon; Apan sa diha nga ang usa ka dautan nga tawo magahari, ang katawohan managpanghupaw.',
        3: 'Bisan kinsa nga nahagugma sa kaalam nagalipay sa iyang amahan; Apan siya nga nakigkauban sa mga bigaon nagausik sa iyang bahandi.',
        4: 'Ang hari tungod sa justicia nagapalig-on sa yuta; Apan kadtong nagapabuhis sa mabug-at gayud nagagun-ob niana.',
        5: 'Ang tawo nga nagaulo-ulo sa iyang isigkatawo. Nagabuklad ug usa ka pukot sa iyang mga lakang.',
        6: 'Diha sa kalapasan sa usa ka dautan nga tawo adunay usa ka lit-ag; Apan ang matarung magaawit ug magalipay.',
        7: 'Ang tawong matarung nakaalinggat sa katungod sa kabus; Ang dautan walay pagsabut sa pagpanghibalo niini',
        8: 'Ang mga mayubiton nagapasilaub sa usa ka ciudad sa usa ka siga; Apan ang mga manggialamon nga tawo nanaglikay sa kaligutgut.',
        9: 'Kong ang usa ka manggialamon nga tawo may usa ka pakiglalis sa usa ka buang nga tawo, Bisan pa siya masuko kun mokatawa, wala gayud ing kapahulayan.',
        10: 'Ang ginauhaw sa dugo nagadumot kaniya nga maoy matarung; Ug alang sa matul-id, sila magapangita sa iyang kinabuhi.',
        11: 'Ang usa ka buang nagabutyag sa tanan niyang kasuko; Apan ang usa ka manggialamon nga tawo nagatago niini ug nagapakahilum niini.',
        12: 'Kong ang usa ka punoan maminaw sa kabakakan, Ang tanan niyang mga alagad lonlon mga dautan.',
        13: 'Ang kabus nga tawo ug ang malupigon magakahibalag; Si Jehova nagapasanag sa mga mata kanilang duruha.',
        14: 'Ang hari nga sa pagkamatinumanon nagahukom sa kabus, Ang iyang trono malig-on sa walay katapusan.',
        15: 'Ang bunal ug ang pagbadlong nagahatag ug kaalam; Apan ang usa ka bata nga pasagdan lamang sa iyang kaugalingon nagapakaulaw sa iyang inahan.',
        16: 'Sa diha nga ang mga dautan modaghan, ang kalapasan mosamot, Apan ang matarung magatan-aw sa ilang pagkapukan.',
        17: 'Sawaya ang imong anak, ug siya magahatag kanimo ug pahulay; Oo, siya magahatag ug kalipay sa imong kalag.',
        18: 'Diin walay panan-awon, ang katawohan nagasalikway sa pagpugong; Apan kadtong nagabantay sa Kasugoan, malipayon siya.',
        19: 'Ang usa ka sulogoon dili masaway pinaagi sa mga pulong; Kay bisan pa nga siya makasa-but, siya dili magtagad.',
        20: 'Nakakita ba ikaw sa usa ka tawo nga madali-dalion sa iyang mga pulong? Aduna pay paglaum sa usa ka buang kay kaniya.',
        21: 'Kadtong nagamatoto sa iyang sulogoon sa dakung pagmatngon gikan sa pagkabata Magahimo kaniya nga usa ka anak sa katapusan.',
        22: 'Ang usa ka tawo nga anaa sa kasuko nagapukaw sa pagkabingkil, Ug ang usa ka masuk-anong tawo nahupngan sa kalapasan.',
        23: 'Ang kagarbo sa tawo makapahimo kaniyang ubos; Apan kadtong mapinaubsanon a espiritu makabaton ug kadungganan.',
        24: 'Bisan kinsa nga makigkauban sa usa ka kawatan nagadumot sa iyang kaugalingong kalag; Siya nakadungog sa pagpanumpa ug dili makapamulong sa bisan unsa.',
        25: 'Ang pagkahadlok ngadto sa tawo nagadala ug usa ka lit-ag; Apan bisan kinsa nga nagabutang sa iyang pagsalig kang Jehova mamaluwas.',
        26: 'Daghang nangita sa kalooy sa magbubuot; Apan ang paghukom sa usa ka tawo nagagikan kang Jehova.',
        27: 'Ang usa ka dili-matarung nga tawo maoy usa ka dulumtanan sa tawong matarung, Ug siya nga matul-id sa dalan maoy usa ka dulumtanan sa tawong dautan.',
    },
    30: {
        1: 'Ang mga pulong ni Agus ang anak nga lalake ni Jache; ang pagpanagna. Ang tawo miingon kang Etiel, ngadto kang Etiel ug kang Ucal:',
        2: 'Sa pagkamatuod ako labi pang mananapon kay sa bisan kinsang tawo, Ug walay pagsabut sa usa ka tawo;',
        3: 'Ug ako wala makakat-on sa kaalam, Ni may kahibalo ako sa Usa nga Balaan.',
        4: 'Kinsa bay nakasaka ngadto sa langit, ug nanaug? Kinsa bay nagahipos sa hangin diha sa iyang mga kinomo? Kinsa bay nakahugpong sa katubigan sulod sa iyang panapton? Kinsa bay nagapahimutang sa tanang mga kinatumyan sa yuta? Kinsa ba ang iyang ngalan, ug kinsa ba ang ngalan sa iyang anak nga lalake, kong ikaw nahibalo?',
        5: 'Ang tagsatagsa ka pulong sa Dios inulay: Siya mao ang usa ka kalasag kanila nga modangup diha kaniya.',
        6: 'Dili ka magdugang sa iyang mga pulong, Tingali unya pagabadlongon ka niya, ug ikaw hikaplagan nga usa ka bakakon.',
        7: 'Duruha ka mga butang ang akong gipangayo kanimo; Ayaw pag-imakuli sila kanako sa dili pa ako mamatay:',
        8: 'Ipahilayo gikan kanako ang kabakakan ug mga bakak; Ayaw ako paghatagi ug kawaladon ni mga bahandi; Pakan-a ako sa makaon nga maoy gikinahanglan alang kanako:',
        9: 'Tingali unya ako mabusog, ug magalimod kanimo, ug magaingon: Kinsa ba si Jehova? Kun tingali unya ako mahimong kabus, ug mangawat, Ug magagamit sa walay hinungdan sa ngalan sa akong Dios.',
        10: 'Ayaw pagbutangbutang sa usa ka sulogoon ngadto sa iyang agalon, Tingali unya siya manghimaraut kanimo, ug ikaw pagailhon nga sad-an.',
        11: 'Adunay usa ka kaliwatan nga nagapanghimaraut sa ilang amahan, Ug wala magbulahan sa ilang inahan.',
        12: 'Adunay usa ka kaliwatan nga ulay ilang kaugalingong mga mata, Ug bisan pa niini wala mahugasi gikan sa ilang pagkahugaw.',
        13: 'Adunay usa ka kaliwatan, Oh pagkamapahitas-on gayud sa ilang mga mata! Ug ang ilang mga tabontabon sa mata napahitaas.',
        14: 'Adunay usa ka kaliwatan kansang mga ngipon ingon sa mga pinuti, ug ang ilang mga tango ingon sa mga cuchillo, Aron sa paglamoy sa mga kabus gikan sa yuta, ug sa hangul gikan sa kinataliwad-an sa mga tawo.',
        15: 'Ang alimatok may duruha ka anak nga baye, nga nagasinggit: Hatagi, hatagi. Adunay totolo ka butang nga dili gayud matagbaw, Oo, upat nga dili moingon: Igo na:',
        16: 'Ang Sheol; ug ang tiyan nga apuli; Ang yuta nga wala matagbaw sa tubig; Ug ang kalayo nga wala magaingon: Igo na.',
        17: 'Ang mata nga nagayubit sa iyang amahan, Ug nagatamay sa pagsugot sa iyang inahan, Ang mga uwak sa walog maoy modagit niini, Ug ang mga gagmayng agila magakaon niini.',
        18: 'Adunay totolo ka butang nga mga katilingad-an kaayo alang kanako, Oo, upat nga wala nako hibaloi:',
        19: 'Ang dalan sa usa ka agila diha sa hangin; Ang dalan sa usa ka halas ibabaw sa usa ka bato; Ang dalan sa usa ka sakayan diha sa kinataliwad-an sa dagat; Ug ang dalan sa usa ka tawo uban sa usa ka dalaga.',
        20: 'Mao man usab ang dalan sa usa ka mananapaw nga babaye; Siya nagakaon ug nagapamahid sa iyang baba, Ug nagaingon: Ako wala makabuhat ug pagkadautan.',
        21: 'Kay alang sa totolo ka butang ang yuta mokurog, Ug alang sa upat, nga kini dili na niya maantus:',
        22: 'Alang sa usa ka sulogoon kong siya mao ang hari; Ug sa usa ka buang kong siya mabusog sa makaon;',
        23: 'Alang sa usa ka dulumtanan nga babaye kong siya maminyo; Ug sa usa ka sulogoon nga babaye nga maoy manununod sa iyang agalon nga babaye.',
        24: 'Adunay upat ka butang nga mga gagmay sa ibabaw sa yuta, Apan sila maalamon gayud kaayo:',
        25: 'Ang olmigas maoy usa ka katawohan nga dili kusgan, Bisan pa niini sila nagaandam sa ilang makaon sa ting-init;',
        26: 'Ang mga conejo maoy usa ka maluyahon nga kaubanan, Bisan pa niini nagabuhat sa ilang mga balay sulod sa mga bato;',
        27: 'Ang mga dulon wala may hari, bisan pa niini silang tanan mopanaw pinaagi sa mga panon;',
        28: 'Ang lawa-lawa nagapangapyot pinaagi sa iyang mga kamot, Bisan pa niini siya anaa sa mga palacio sa mga hari.',
        29: 'Adunay totolo ka butang nga sa ilang pagpanlakat mga matahum man, Oo, upat nga mga matahum sa ilang mga pagpanaw:',
        30: 'Ang leon, nga maoy labing gamhanan taliwala sa tanang mga mananap, Ug dili motalikod tungod sa bisan unsa man;',
        31: 'Ang iro sa pangayam; ang kanding nga lake usab; Ug ang hari diin batok kaniya nga walay mga pag-alsa.',
        32: 'Kong ikaw nakabuhat sa binuang sa pagpatuboy sa imong kaugalingon, O kong ikaw naghunahuna ug dautan, Isap-ong ang imong kamot ibabaw sa imong baba.',
        33: 'Kay ang pagbatil sa gatas nagadala ug mantekilya, Ug ang paglubag sa ilong nagapagula sa dugo; Busa ang pagpugos sa kaligutgut nagadala ug pakig-away.',
    },
    31: {
        1: 'Ang mga pulong ni hari Lemuel; ang pagpanagna nga gitudlo kaniya sa iyang inahan.',
        2: 'Unsa, anak ko? ug unsa, Oh anak sa akong tagoangkan? Ug unsa, Oh anak sa akong mga panaad?',
        3: 'Ayaw pag-ihatag ang imong kusog ngadto sa mga babaye, Ni ang imong mga dalan nianang nakapalaglag sa mga hari.',
        4: 'Dili angay alang sa mga hari, Oh Lemuel, dili angay alang sa mga hari ang pag-inum sa vino; Ni alang sa mga principe ang pag-ingon: Hain ang maisug nga ilimnon?',
        5: 'Tingali unya manginum sila, ug malimot sa Kasugoan, Ug balit-aron ang justicia alang sa bisan kinsa nga ginasakit.',
        6: 'Hatagi ug maisug nga ilimnon kadtong andam na sa pagkahanaw, Ug vino niadtong ginapaitan sa kalag:',
        7: 'Paimna siya, ug pahikalimti ang iyang kakabus, Ug ayaw na pagpahinumdumi ang iyang pagka-makalolooy.',
        8: 'Bukha ang imong baba alang sa amang, Diha sa kaayohan sa tanan niadtong mga biniyaan.',
        9: 'Bukha ang imong baba, maghukom ka sa pagkamatarung, Ug maghatag ka ug justicia sa mga kabus ug hangul.',
        10: 'Kinsay makakaplag sa usa ka babaye nga takus? Kay ang iyang bili labaw pa kay sa mahal nga mga bato.',
        11: 'Ang kasingkasing sa iyang bana nagasalig kaniya, Ug siya wala makulangi sa ganancia.',
        12: 'Siya nagabuhat kaniya sa maayo ug dili sa dautan Sa tibook nga mga adlaw sa iyang kinabuhi.',
        13: 'Siya nagapangita ug balhibo sa carnero ug lanot sa lino, Ug sa kinabubut-on nagabuhat uban sa iyang kamot.',
        14: 'Siya sama sa mga sakayan-sa-patigayon; Siya nagadala sa iyang tinapay gikan sa halayo.',
        15: 'Siya mobangon usab samtang gabii pa, Ug nagahatag sa kalan-on sulod sa iyang panimalay, Ug ang ilang mga buhat alang sa iyang mga sulogoong dalaga.',
        16: 'Siya nagahunahuna ug usa ka baul, ug nagapalit niini; Uban sa bunga sa iyang mga kamot siya nagatanum ug usa ka parrasan.',
        17: 'Ginabaksan niya ug kalig-on ang iyang mga hawak, Ug ginapabaskog niya ang iyang mga bukton.',
        18: 'Siya nahibalo nga ang iyang baligya makaganancia; Ang iyang lamparahan dili mapalong sa pagkagabii.',
        19: 'Ginabutang niya ang iyang mga kamot sa bilikan, Ug ang mga kamot nagapugong sa kalinyasan.',
        20: 'Ginatuy-od niya ang iyang kamot ngadto sa mga kabus; Oo, nagatunol siya sa iyang mga kamot ngadto sa mga hangul.',
        21: 'Siya dili mahadlok sa nieve alang sa iyang panimalay; Kay ang iyang sulod-balay gibistihan sa mapula.',
        22: 'Siya nagabuhat alang sa iyang kaugalingon ug mga alfombra; Ang iyang saput lino nga manipis ug purpura.',
        23: 'Ang iyang bana inila diha sa mga ganghaan, Sa diha nga siya molingkod uban sa mga anciano sa yuta.',
        24: 'Siya nagabuhat ug mga saput nga lino ug nagabaligya kanila, Ug nagahatud ug mga bakus ngadto sa magpapatigayon.',
        25: 'Kusog ug pagkahalangdon mao ang iyang saput; Ug siya mokatawa sa panahon nga umalabut.',
        26: 'Siya nagabuka sa iyang baba uban ang pagkamanggialamon; Ug ang balaod sa pagkamaloloy-on maoy anaa sa tumoy sa iyang dila.',
        27: 'Siya nagasud-ong ug maayo sa mga paagi sa iyang sulod-balay, Ug dili mokaon sa tinapay sa pagkatapulan.',
        28: 'Ang iyang mga anak mobangon, ug magatawag kaniya nga bulahan; Ang iyang bana usab, ug siya nagadayeg kaniya, nga nagaingon:',
        29: 'Daghang mga anak nga babaye nga nanagbuhat sa pagkatakus gayud, Apan ikaw milabaw kanilang tanan.',
        30: 'Ang katahum malimbongon, ug ang kaanyag kakawangan lamang; Apan ang usa ka babaye nga mahadlok kang Jehova, siya pagadayegon.',
        31: 'Hatagi siya sa bunga sa iyang mga kamot; Ug papagdayega kaniya ang iyang mga buhat diha sa mga ganghaan.',
    },
}
